window.CT_QUESTOES_PROVA=[{"id":"2120454","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Do Contrato Estimatório (arts. 534 a 537)","enunciado":"De acordo com o Código Civil, a entrega de bens móveis ao consignatário, que fica autorizado a vendê-los, pagando àquele o preço ajustado, caracteriza o","alternativas":[{"letra":"A","texto":"contrato de representação."},{"letra":"B","texto":"contrato estimatório."},{"letra":"C","texto":"agenciamento."},{"letra":"D","texto":"acordo de comissionamento."},{"letra":"E","texto":"pacto de corretagem."}],"gabarito":"B","pct":"81,21"},{"id":"2120459","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Prescrição e Decadência (arts. 189 a 211)","enunciado":"Assinale a opção em que é apresentado o número de anos a que corresponde o prazo prescricional aplicado aos casos em que a ofensa ao direito autoral se assemelhe a um descumprimento contratual.","alternativas":[{"letra":"A","texto":"2"},{"letra":"B","texto":"3"},{"letra":"C","texto":"4"},{"letra":"D","texto":"5"},{"letra":"E","texto":"10"}],"gabarito":"E","pct":"64,06"},{"id":"2120467","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Da Assunção de Dívida (arts. 299 a 303)","enunciado":"Caso terceiro assuma a obrigação do devedor, com o consentimento expresso do credor, ficando exonerado o devedor primitivo, dá-se a","alternativas":[{"letra":"A","texto":"sub-rogação subjetiva."},{"letra":"B","texto":"cessão de crédito."},{"letra":"C","texto":"novação subjetiva."},{"letra":"D","texto":"assunção de dívida."},{"letra":"E","texto":"remissão da dívida."}],"gabarito":"D","pct":"82,76"},{"id":"2120471","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Dos Direitos da Personalidade (arts. 11 a 21)","enunciado":"Os direitos da personalidade, em regra, são:\n\n \nI intransmissíveis.\n\n \nII irrenunciáveis.\n\n \nIII extrapatrimoniais.\n\n \nIV absolutos.\n\n \nV absolutamente indisponíveis.\n\n \nAssinale a opção correta.","alternativas":[{"letra":"A","texto":"Apenas os itens II e V estão certos."},{"letra":"B","texto":"Apenas os itens I, III e V estão certos."},{"letra":"C","texto":"Apenas os itens II, III e IV estão certos."},{"letra":"D","texto":"Apenas os itens I, II, III e IV estão certos."},{"letra":"E","texto":"Todos os itens estão certos."}],"gabarito":"D","pct":"70,36"},{"id":"2120472","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Do Casamento (arts. 1.511 a 1.582)","enunciado":"É nulo o casamento contraído","alternativas":[{"letra":"A","texto":"entre indivíduos menores de idade."},{"letra":"B","texto":"em razão de vício de vontade."},{"letra":"C","texto":"por infringência de impedimento."},{"letra":"D","texto":"por incapacidade de manifestação inequívoca de consentimento."},{"letra":"E","texto":"por incompetência da autoridade celebrante."}],"gabarito":"C","pct":"71,11"},{"id":"2120474","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Civil","assunto":"Jurisprudência dos Tribunais Superiores sobre Direito das Coisas","enunciado":"De acordo com entendimento do Superior Tribunal de Justiça, para que a hipoteca seja oponível erga omnes, ela deverá ser","alternativas":[{"letra":"A","texto":"constituída por meio de contrato."},{"letra":"B","texto":"imposta pela lei."},{"letra":"C","texto":"assinada por duas testemunhas."},{"letra":"D","texto":"declarada em sentença judicial."},{"letra":"E","texto":"inscrita no cartório de registro de imóveis."}],"gabarito":"E","pct":"82,04"},{"id":"2694859","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Da Cessão de Crédito (arts. 286 a 298)","enunciado":"João fez um empréstimo de bem fungível a Antônio. Posteriormente, cedeu esse crédito a José e comunicou formalmente a Antônio quanto à cessão ocorrida. Com base nas informações e no Código Civil de 2002, é correto afirmar que:","alternativas":[{"letra":"A","texto":"João não poderia ceder o crédito sem a aquiescência de Antônio, razão pela qual a cessão é inválida perante terceiros;"},{"letra":"B","texto":"João não poderia ceder o crédito sem a aquiescência de Antônio, razão pela qual a cessão é ineficaz perante terceiros;"},{"letra":"C","texto":"João não poderia ceder o crédito sem a aquiescência de Antônio, razão pela qual a cessão é inexistente perante terceiros;"},{"letra":"D","texto":"João poderia ceder o crédito sem a aquiescência de Antônio, bastando a notificação;"},{"letra":"E","texto":"Antônio poderá pagar a dívida tanto a João quanto a José e receber a devida quitação."}],"gabarito":"D","pct":"89,53"},{"id":"2694860","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Da Doação (arts. 538 a 564)","enunciado":"Em relação ao Instituto da Doação, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a doação à entidade futura caducará se, em dois anos, não estiver constituída regularmente;"},{"letra":"B","texto":"a doação feita a nascituro torná-lo-á dono do objeto doado desde a concepção;"},{"letra":"C","texto":"a revogação da doação por ingratidão pode ser pleiteada dentro de dois anos do fato;"},{"letra":"D","texto":"o doador não pode fixar prazo para o donatário declarar se aceita ou não o objeto doado;"},{"letra":"E","texto":"se realizada doação pura a absolutamente incapaz, será exigido o aceite da mãe e/ou do pai."}],"gabarito":"A","pct":"68,62"},{"id":"2694865","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Do Condomínio Geral (arts. 1.314 a 1.358-A)","enunciado":"Marcos, João e Fernando querem comprar juntos uma máquina de impressão, cujo valor no mercado é muito alto, pois conta com tecnologia avançada. Cada um usará a máquina quatro meses no ano e, dessa forma, poderão ratear as despesas de aquisição.\n\nCom base nas informações prestadas, bem como na legislação civil vigente, poderão valer-se, para aquisição da máquina:","alternativas":[{"letra":"A","texto":"do condomínio em multipropriedade, previsto no Art. 1.358-B do Código Civil. Para dirimir eventuais questões (deliberações), como tempo para manutenção e seus custos, farão uma convenção com as devidas cláusulas, já que a lei é omissa;"},{"letra":"B","texto":"do condomínio em multipropriedade, previsto no Art. 1.358-B do Código Civil. Para dirimir eventuais questões (deliberações), como tempo para manutenção e seus custos, a lei estabelece o quórum de maioria absoluta;"},{"letra":"C","texto":"do condomínio voluntário, previsto no Art. 1.314 do Código Civil. Para dirimir eventuais questões (deliberações), como tempo para manutenção e seus custos, farão uma convenção com as devidas cláusulas, já que a lei é omissa;"},{"letra":"D","texto":"do condomínio voluntário, previsto no Art. 1.314 do Código Civil. Para dirimir eventuais questões (deliberações), como tempo para manutenção e seus custos, a lei estabelece quórum de maioria absoluta;"},{"letra":"E","texto":"do condomínio em multipropriedade, previsto no Art. 1.358-B do Código Civil. A lei estabelece que o administrador deverá dirimir eventuais questões (deliberações), como tempo para manutenção e seus custos."}],"gabarito":"D","pct":"37,09"},{"id":"2694866","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Do Casamento (arts. 1.511 a 1.582)","enunciado":"Maria e João, brasileiros naturalizados, casaram-se formalmente em Las Vegas, Estados Unidos, no ano passado, em uma grande celebração. Voltaram para o Brasil e decidiram comprar um apartamento maior, já que Maria descobriu-se grávida de três semanas, razão pela qual o apartamento atual estava pequeno. Muito felizes com a notícia e empolgados com a nova casa escolhida, encaminharam-se ao cartório para lavrar a escritura de compra e venda do novo lar. Lá chegando, o tabelião informou-os que não poderia constar em suas qualificações o estado civil de “casado(a)”, o que os deixou realmente muito tristes.\n\nA razão da atitude do tabelião, segundo a legislação civil, deu-se porque, no Brasil, o casamento realizado no exterior é:","alternativas":[{"letra":"A","texto":"inexistente, tendo que ser repetido em território nacional para adquirir existência, validade e eficácia;"},{"letra":"B","texto":"existente, tendo que passar por processo de apostilamento e posterior registro no RCPN, para adquirir validade e eficácia;"},{"letra":"C","texto":"existente e válido, tendo que passar por processo de apostilamento e posterior registro no RCPN, para adquirir eficácia;"},{"letra":"D","texto":"existente e eficaz, tendo que passar por processo de apostilamento e posterior registro no RCPN, para adquirir validade;"},{"letra":"E","texto":"existente, válido e eficaz, sendo incorreta a informação passada pelo tabelião."}],"gabarito":"B","pct":"34,43"},{"id":"2694868","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Do Direito de Representação na Sucessão Legítima (arts. 1.851 a 1.856)","enunciado":"João, pai de Daniel, Maria, José e Paulo, morreu e deixou cinquenta milhões de reais em patrimônio. Não deixou testamento. Ficou constatado, por sentença penal condenatória transitada em julgado, que Daniel, aborrecido por ter perdido o cargo de presidente da empresa da família, envenenou o pai, causando-lhe a morte. Não houve ação cível para excluí-lo da herança. Daniel tem um filho chamado Peter, que terá que conviver com o fato de o pai ser um assassino. Maria renunciou à herança. Maria tem duas filhas: Paula e Poliana. José já era morto quando da morte do pai e tinha um filho Manoel. Paulo teve um infarto logo após receber a notícia de que seu pai havia sido envenenado pelo irmão e morrido. Não tinha filhos, apenas mulher, Cláudia, com quem foi casado pelo regime de separação absoluta e voluntária de bens.\n\nCom base no enunciado, na legislação civil e na jurisprudência dos Tribunais Superiores, é correto afirmar que:","alternativas":[{"letra":"A","texto":"Daniel herdará, já que não houve ação cível para excluí-lo da herança;"},{"letra":"B","texto":"Paula e Poliana herdarão como se Maria já fosse morta quando o pai morreu;"},{"letra":"C","texto":"Daniel não herdará, mas será o administrador dos bens do filho que herdará por cabeça;"},{"letra":"D","texto":"Cláudia não herdará porque o regime de bens não permite;"},{"letra":"E","texto":"Manoel herdará a quota-parte do pai."}],"gabarito":"E","pct":"82,97"},{"id":"2694870","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Disposições Gerais - Pessoas Jurídicas (arts. 40 a 52)","enunciado":"São pessoas jurídicas de direito privado, segundo o Código Civil:","alternativas":[{"letra":"A","texto":"sociedades, fundações, organizações religiosas e territórios;"},{"letra":"B","texto":"associações, fundações, organizações religiosas e empresas individuais de responsabilidade limitada;"},{"letra":"C","texto":"sociedades de economia mista e empresas públicas;"},{"letra":"D","texto":"União, Estados, Municípios e Territórios;"},{"letra":"E","texto":"associações, sociedades, fundações, organizações religiosas e partidos políticos."}],"gabarito":"E","pct":"72,67"},{"id":"2694871","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Dos Direitos de Vizinhança (arts. 1.277 a 1.313)","enunciado":"As árvores da casa de João são muito bonitas e frondosas. Seus galhos ultrapassaram a linha do muro divisório e acabaram por passar por cima deste, fazendo sombra na piscina de José. Apesar das reclamações de José, João não as aparava. Eventualmente, caíam até frutos na casa de José.\n\nBaseado no enunciado e na legislação civil, é correto afirmar que:","alternativas":[{"letra":"A","texto":"José pode cortar os galhos das árvores que ultrapassaram o muro e invadiram seu terreno até o plano vertical divisório e os frutos que caírem em seu terreno são seus;"},{"letra":"B","texto":"José pode cortar os galhos das árvores que ultrapassaram o muro e invadiram seu terreno até o plano vertical divisório, mas deve devolver os frutos que caírem em seu terreno;"},{"letra":"C","texto":"José não pode cortar os galhos das árvores que ultrapassaram o muro e invadiram seu terreno até o plano vertical divisório, mas os frutos que caírem em seu terreno são seus;"},{"letra":"D","texto":"José não pode cortar os galhos das árvores que ultrapassaram o muro e invadiram seu terreno até o plano vertical divisório, bem como deve devolver os frutos que caírem em seu terreno;"},{"letra":"E","texto":"a possibilidade ou não de José cortar os galhos das árvores que ultrapassaram o muro e invadiram seu terreno até o plano vertical divisório e se apropriar dos frutos dependerá de Lei Municipal específica."}],"gabarito":"A","pct":"95,57"},{"id":"2694872","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Da Transação (arts. 840 a 850)","enunciado":"Jussara atropelou, por acidente, Joelma. Ao verificar as consequências de sua desatenção, prestou a assistência possível e, ao final, ainda pagou todas as despesas hospitalares e as diárias da vítima pelo período em que ficou afastada de seu trabalho como diarista.\n\nJoelma, então, assinou quitação com a seguinte redação:\n\n“Considerando que Jussara pagou todas as despesas hospitalares e as diárias de meu trabalho, outorgo-lhe, a esse título, a mais ampla e plena quitação, para mais nada reclamar, em juízo ou fora dele”.\n\nUm mês depois, eclodiram novas complicações médicas, decorrentes do acidente. Jussara, no entanto, negou-se a tornar a apoiar Joelma, diante da quitação já outorgada.\n\nJoelma, em consequência, ajuíza ação indenizatória por danos morais em face de Jussara.\n\nNesse caso, é correto afirmar que a quitação outorgada:","alternativas":[{"letra":"A","texto":"não foi válida, por ter se realizado em âmbito extrajudicial sem a assistência de advogados;"},{"letra":"B","texto":"abrangia, também, eventuais danos morais, uma vez que era ampla e plena, para mais nada reclamar, em juízo ou fora dele;"},{"letra":"C","texto":"não contempla as complicações supervenientes, desconhecidas da vítima que acabara de sofrer um grave acidente;"},{"letra":"D","texto":"pode ser revogada, diante da conduta de má-fé por parte de Jussara que parou de prestar qualquer apoio a Joelma posteriormente;"},{"letra":"E","texto":"não contém os requisitos do Art. 320 do Código Civil (o valor e a espécie da dívida quitada, o nome do devedor, ou quem por este pagou, o tempo e o lugar do pagamento, com a assinatura do credor, ou do seu representante), de modo que, mesmo sendo possível identificar que foi paga a dívida, não valerá."}],"gabarito":"C","pct":"76,07"},{"id":"2694874","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Civil","assunto":"Do Mandato (arts. 653 a 692)","enunciado":"Jacqueline celebrou promessa de compra e venda de imóvel de sua propriedade em 2019. Logo, foi diagnosticada com um câncer terminal, razão pela qual outorgou mandato a Elisângela, sua melhor amiga, para todas as medidas tendentes à conclusão do negócio.\n\nEm 03/04/2020, o adquirente integraliza o preço, depositando-o na conta de Jacqueline. Em 05/04/2020, Jacqueline falece, sem que tenha sido possível lavrar a escritura definitiva e registrá-la.\n\nNesse caso, é correto afirmar que:","alternativas":[{"letra":"A","texto":"com a morte de Jacqueline, extinguiu-se automaticamente o mandato, razão pela qual Elisângela não poderá ultimar o negócio;"},{"letra":"B","texto":"o óbito do mandante não é causa de extinção do mandato com objeto definido, em que apenas a consecução deste escopo faz cessar a representação;"},{"letra":"C","texto":"com a morte de Jacqueline, extinguiu-se automática e inexoravelmente o mandato, razão pela qual Elisângela só poderá ultimar o negócio na condição de gestora de negócios;"},{"letra":"D","texto":"o óbito do mandante, via de regra, faz cessar o mandato, no entanto, é possível, à luz das peculiaridades do caso concreto, que Elisângela assine a escritura e ultime a transferência;"},{"letra":"E","texto":"a morte de Jacqueline fez cessar o mandato, no entanto, após integralizado o preço, o negócio já estava aperfeiçoado, bastando que o adquirente levasse o contrato e a prova da quitação ao Registro Geral de Imóveis para concluir a transferência."}],"gabarito":"D","pct":"65,24"},{"id":"2120484","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Jurisprudência dos Tribunais Superiores sobre Tutela Provisória","enunciado":"Assinale a opção correta a respeito da tutela provisória.","alternativas":[{"letra":"A","texto":"Na hipótese de efetivação parcial da tutela cautelar antecedente, o pedido principal deve ser formulado pelo autor dentro do prazo de 30 dias, sob pena de perda da eficácia da medida."},{"letra":"B","texto":"É desnecessário pronunciamento judicial expresso sobre a obrigação de indenizar o dano causado pela execução de tutela antecipada posteriormente revogada, por ser consequência natural da improcedência do pedido."},{"letra":"C","texto":"A concessão de tutela de evidência independe da comprovação da urgência (perigo de dano ou risco ao resultado útil do processo), sendo admitida quando as alegações de fato puderem ser comprovadas apenas documentalmente e houver tese firmada em julgamento de casos repetitivos ou em súmula vinculante. Contudo, nessa hipótese, o juiz não poderá decidir liminarmente sem ouvir a parte contrária."},{"letra":"D","texto":"O Supremo Tribunal Federal fixou o entendimento de que é válida a edição de lei ou de ato normativo que vede a concessão de medida liminar pela via do mandado de segurança."},{"letra":"E","texto":"Pode-se afirmar que, do ponto de vista da extensão, a cognição da tutela provisória seria superficial e, do ponto de vista da profundidade, essa cognição seria plena."}],"gabarito":"B","pct":"45,08"},{"id":"2120497","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Da Ação Rescisória (arts. 966 a 975)","enunciado":"Acerca da sistemática das ações rescisórias no direito processual civil, assinale a opção correta.","alternativas":[{"letra":"A","texto":"De acordo com o Superior Tribunal de Justiça, o advogado é parte ilegítima para figurar no polo passivo da ação rescisória, ainda que tenham sido arbitrados honorários sucumbenciais a seu favor na ação rescindenda."},{"letra":"B","texto":"Conforme entendimento do Superior Tribunal de Justiça, há uma causa petendi aberta durante o juízo rescindente, pois o tribunal não se vincula aos dispositivos de lei apontados pelo autor como literalmente violados."},{"letra":"C","texto":"O Superior Tribunal de Justiça fixou o entendimento de que é cabível ação rescisória contra decisão do presidente do tribunal proferida em suspensão de liminar e de sentença, desde que transitada em julgado."},{"letra":"D","texto":"Admite-se a propositura de ação rescisória se a decisão impugnada contrariar manifestamente norma jurídica. Contudo, não se entende como tal a decisão que tenha sido embasada em acórdão proferido em julgamento de casos repetitivos sem que se tenha considerado a existência de distinção entre a questão discutida no processo e o padrão decisório que lhe deu fundamento."},{"letra":"E","texto":"Segundo o Código de Processo Civil, a decisão de mérito transitada em julgado pode ser rescindida quando obtiver o autor, posteriormente ao trânsito em julgado, prova nova cuja existência ignorava ou de que não pôde fazer uso, capaz, por si só, de lhe assegurar pronunciamento favorável. Conforme entendimento do Superior Tribunal de Justiça, essa previsão se refere à prova documental e pericial, excluída, portanto, a testemunhal."}],"gabarito":"A","pct":"46,30"},{"id":"2120500","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Do Agravo de Instrumento (arts. 1.015 a 1.020)","enunciado":"Assinale a opção correta em relação ao pronunciamento judicial.","alternativas":[{"letra":"A","texto":"Eventual informação equivocada prestada por sistema eletrônico de tribunal não pode ser utilizada como parâmetro para aferição da tempestividade do recurso."},{"letra":"B","texto":"As decisões interlocutórias acerca da instrução probatória não são impugnáveis por agravo de instrumento ou pela via mandamental, sendo cabível a sua impugnação diferida pela via da apelação."},{"letra":"C","texto":"A prolação de sentença objeto de recurso de apelação acarreta a perda superveniente do objeto de agravo de instrumento pendente de julgamento, ainda que este verse sobre consumação da prescrição ou inversão do ônus da prova."},{"letra":"D","texto":"Não se revela cabível a interposição de agravo de instrumento contra decisões que versem sobre o mero requerimento de expedição de ofício para apresentação ou juntada de documentos ou coisas, dada a taxatividade mitigada das decisões impugnáveis mediante agravo."},{"letra":"E","texto":"Impede-se a fixação de honorários recursais em relação aos pedidos autônomos dos demais litisconsortes, nos casos em que haja cumulação simples subjetiva de pedidos e o provimento do recurso atinja apenas o pedido de um dos litisconsortes facultativos."}],"gabarito":"B","pct":"36,48"},{"id":"2120502","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Do Cumprimento da Sentença (arts. 513 a 538)","enunciado":"Assinale a opção correta no tocante à liquidação e ao cumprimento de sentença.","alternativas":[{"letra":"A","texto":"Por serem considerados verba de natureza alimentar, os créditos decorrentes de honorários advocatícios sucumbenciais titularizados pelo advogado têm preferência em relação ao crédito principal titularizado por seu cliente."},{"letra":"B","texto":"Admite-se a alegação de prescrição eventualmente ocorrida na fase de conhecimento em sede cumprimento de sentença."},{"letra":"C","texto":"Na hipótese de condenação em obrigação de fazer e de pagar, entende-se que o ajuizamento de execução da obrigação de fazer interrompe o prazo para a execução da obrigação de pagar, em razão do princípio da unidade do título executivo."},{"letra":"D","texto":"A regra de contagem em dobro aos litisconsortes que tiverem diferentes procuradores, de escritórios de advocacia distintos, aplica-se ao rito da impugnação ao cumprimento de sentença."},{"letra":"E","texto":"Admite-se a adoção de medidas executivas atípicas para a satisfação do crédito exequendo em casos de direitos patrimoniais disponíveis, revelando-se legítima a utilização da quebra de sigilo bancário destinada a esse fim."}],"gabarito":"D","pct":"49,04"},{"id":"2120504","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Da Intervenção de Terceiros (arts. 119 a 138)","enunciado":"Assinale a opção correta em relação à intervenção de terceiros, conforme disposto no Código de Processo Civil/2015.","alternativas":[{"letra":"A","texto":"Deve ser extinta a denunciação da lide apresentada intempestivamente pelo réu nas hipóteses em que o denunciado conteste apenas a pretensão de mérito da demanda principal."},{"letra":"B","texto":"Considera-se possível o ingresso de terceiro como assistente simples, desde que demonstrada a presença de interesse jurídico, revelando-se como tal o interesse corporativo."},{"letra":"C","texto":"Em ação de reparação de danos, a seguradora denunciada que aceitar a denunciação ou contestar o pedido do autor poderá ser condenada, direta e solidariamente, junto com o segurado, ao pagamento da indenização devida à vítima, nos limites contratados na apólice."},{"letra":"D","texto":"Admite-se a denunciação da lide àquele que estiver obrigado, por lei ou pelo contrato, a indenizar, em ação regressiva, o prejuízo de quem for vencido no processo, ainda que introduzir fundamento novo à causa."},{"letra":"E","texto":"É suficiente para a instauração do incidente de desconsideração da personalidade jurídica a demonstração de inexistência de patrimônio da pessoa jurídica ou de dissolução irregular da empresa sem a devida baixa na junta comercial."}],"gabarito":"C","pct":"70,33"},{"id":"2120544","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Civil","assunto":"Jurisprudência dos Tribunais Superiores sobre Processo de Execução","enunciado":"Pode ajuizar ação de execução de alimentos em proveito de criança e adolescente o Ministério Público, na condição de","alternativas":[{"letra":"A","texto":"representante processual, quando não existir Defensoria Pública instalada nem em funcionamento na localidade."},{"letra":"B","texto":"representante processual, quando o exercício do poder familiar dos pais estiver suspenso."},{"letra":"C","texto":"substituto processual, independentemente de qualquer circunstância."},{"letra":"D","texto":"representante processual, quando os direitos do menor estiverem ameaçados ou violados por omissão dos pais ou responsáveis."},{"letra":"E","texto":"representante processual, a pedido dos pais ou responsáveis do menor."}],"gabarito":"C","pct":"52,55"},{"id":"2694882","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Petição Inicial (arts. 319 a 331)","enunciado":"João ajuizou ação buscando a revisão do contrato de financiamento firmado com o banco ABC. Na petição inicial, João não especificou as obrigações contratuais controvertidas, tampouco indicou o valor incontroverso do débito. Ao receber a petição inicial, o juiz determinou a intimação de João para indicar/especificar as questões acima, o que não foi cumprido no prazo legal, ensejando o indeferimento da petição inicial por inépcia.\n\nDiante dessa situação hipotética, é correto afirmar que:","alternativas":[{"letra":"A","texto":"interposta apelação cível, é facultado ao juiz, no prazo de cinco dias, retratar-se;"},{"letra":"B","texto":"a petição inicial não poderia ser indeferida por inépcia, pois o caso concreto não se encaixa nas hipóteses legais de inépcia;"},{"letra":"C","texto":"interposta apelação cível, não havendo retratação, o juiz determinará a intimação do banco ABC para responder ao recurso;"},{"letra":"D","texto":"interposta apelação cível, se o recurso for provido pelo tribunal, o prazo para contestação será de quinze dias a partir da publicação do acórdão de julgamento;"},{"letra":"E","texto":"o juiz não poderia indeferir a petição inicial sem citar o banco ABC para apresentar sua contestação, cabendo a ele arguir a inépcia em preliminar de contestação."}],"gabarito":"A","pct":"78,51"},{"id":"2694883","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Prova Documental (arts. 405 a 438)","enunciado":"Sobre a força probante dos documentos, é correto afirmar que:","alternativas":[{"letra":"A","texto":"o telegrama, o radiograma ou qualquer outro meio de transmissão têm a mesma força probatória do documento particular, ainda que o original constante da estação expedidora não tenha sido assinado pelo remetente;"},{"letra":"B","texto":"a nota escrita pelo credor em qualquer parte de documento representativo de obrigação, se não estiver assinada, não faz prova em benefício do devedor;"},{"letra":"C","texto":"os livros empresariais provam contra seu autor, sendo lícito ao empresário, todavia, demonstrar, por todos os meios permitidos em direito, que os lançamentos não correspondem à verdade dos fatos;"},{"letra":"D","texto":"quando o documento contiver entrelinha, emenda, borrão ou cancelamento em ponto substancial e sem ressalva, não poderá ser valorado pelo juiz;"},{"letra":"E","texto":"o juiz não pode determinar, de ofício, à parte a exibição parcial dos livros e dos documentos, para extrair deles a suma que interessar ao litígio, bem como reproduções autenticadas."}],"gabarito":"C","pct":"77,78"},{"id":"2694884","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Dos Incidentes de Assunção e Arguição (arts. 947 a 950)","enunciado":"Sobre o incidente de assunção de competência, é correto afirmar que:","alternativas":[{"letra":"A","texto":"é admissível sua instauração perante o juízo de primeiro grau;"},{"letra":"B","texto":"o acórdão proferido em assunção de competência não vincula todos os juízes e órgãos fracionários dentro do tribunal;"},{"letra":"C","texto":"não é admissível quando se tratar de processo de competência originária dos tribunais;"},{"letra":"D","texto":"é cabível para prevenir a divergência entre câmaras do tribunal sobre relevante questão de direito;"},{"letra":"E","texto":"para sua admissão, além da relevante questão de direito, deve haver repetição em múltiplos processos."}],"gabarito":"D","pct":"85,87"},{"id":"2694887","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Ordem dos Processos no Tribunal (arts. 929 a 946)","enunciado":"No julgamento de apelação cível, após o relator proferir seu voto, tendo sido acompanhado pelo primeiro vogal, o segundo vogal pediu vista dos autos, pois considerou que não estava habilitado a proferir seu voto imediatamente, demandando uma análise mais detalhada do caso concreto.\n\nDiante dessa situação, é correto afirmar que:","alternativas":[{"letra":"A","texto":"o prazo máximo e improrrogável para vista dos autos será de quinze dias;"},{"letra":"B","texto":"a vista dos autos pressupõe a inclusão do processo na sessão subsequente para que o voto seja proferido, sem a possibilidade de prorrogação;"},{"letra":"C","texto":"ao requerer vista dos autos, o vogal fica vinculado ao julgamento do recurso até que esteja pronto para votar, independentemente de prazo;"},{"letra":"D","texto":"se o vogal que fez o pedido de vista ainda não se sentir habilitado a votar, o presidente poderá retomar o julgamento e proclamar o resultado, computando-se, apenas, os votos proferidos;"},{"letra":"E","texto":"se o vogal não devolver os autos tempestivamente ou se não requerer prorrogação do prazo de vista, o presidente requisitará os autos para julgamento do recurso, convocando substituto para proferir voto, se aquele que fez o pedido de vista não se sentir habilitado a votar."}],"gabarito":"E","pct":"82,76"},{"id":"2694889","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Intervenção de Terceiros (arts. 119 a 138)","enunciado":"Sobre o incidente de desconsideração da personalidade jurídica, é correto afirmar que:","alternativas":[{"letra":"A","texto":"não cabe instrução probatória no incidente de desconsideração da personalidade jurídica;"},{"letra":"B","texto":"a instauração do incidente de desconsideração da personalidade jurídica, seja na petição inicial ou em qualquer fase do processo, não enseja a suspensão do processo;"},{"letra":"C","texto":"instaurado o incidente de desconsideração da personalidade jurídica, o sócio ou a pessoa jurídica será intimado para manifestar-se e requerer as provas cabíveis no prazo de quinze dias;"},{"letra":"D","texto":"é cabível em todas as fases do processo de conhecimento, no cumprimento de sentença e na execução fundada em título executivo extrajudicial;"},{"letra":"E","texto":"acolhido o pedido de desconsideração da personalidade jurídica, a alienação ou a oneração de bens, havida em fraude de execução, deverá ser objeto de ação própria para ser declarada ineficaz em relação ao requerente."}],"gabarito":"D","pct":"72,88"},{"id":"2694890","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Do Cumprimento da Sentença (arts. 513 a 538)","enunciado":"Sobre o cumprimento de sentença, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a sentença arbitral não é título executivo judicial e não pode ser objeto de cumprimento de sentença;"},{"letra":"B","texto":"em sede de impugnação, se a fazenda pública arguir excesso à execução, mas não indicar o valor devido, o argumento deve ser apreciado, em razão do interesse público;"},{"letra":"C","texto":"a decisão que fixa a multa por descumprimento de obrigação de fazer é passível de cumprimento provisório, sendo permitido o levantamento do valor independentemente do trânsito em julgado da sentença favorável à parte;"},{"letra":"D","texto":"o cumprimento de sentença não pode ser promovido no local onde se encontrem os bens sujeitos à execução, sendo de competência exclusiva do juízo de origem;"},{"letra":"E","texto":"ainda que atribuído efeito suspensivo à impugnação, é lícito ao exequente requerer o prosseguimento da execução, oferecendo e prestando, nos próprios autos, caução suficiente e idônea a ser arbitrada pelo juiz."}],"gabarito":"E","pct":"79,09"},{"id":"2694892","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Competência Interna (arts. 42 a 69)","enunciado":"Texto 1\n\nAlexandre, menor absolutamente incapaz, ajuizou ação pelo procedimento comum, representado por seu genitor, em face de operadora de plano de saúde, pleiteando a condenação desta a custear determinado tratamento cuja cobertura lhe fora negada, bem como a lhe pagar verba reparatória de danos morais.\n\nA petição inicial, na qual também foi requerida a concessão de tutela provisória para o fim de se assegurar, desde logo, a cobertura do tratamento, foi instruída com cópia do contrato celebrado com a operadora, com a documentação comprobatória dos pagamentos das mensalidades e com laudos médicos atestando a necessidade imediata do tratamento prescrito para o autor, além de outros documentos essenciais para a propositura da ação.\n\nA ação foi ajuizada em um juízo cível da Comarca de Goiânia, embora o menor e o seu representante legal residam em Serranópolis, tendo a operadora demandada, por sua vez, sede na cidade de São Paulo/SP, sem ter qualquer estabelecimento ou filial na capital goiana. Quanto ao contrato, foi ele entabulado no Município em que reside a parte autora.\n\nConsiderando a situação descrita no texto 1, é correto afirmar que:","alternativas":[{"letra":"A","texto":"não há qualquer vício de incompetência;"},{"letra":"B","texto":"caso entenda que o juízo é incompetente para julgar o feito, caberá à ré ofertar o incidente de exceção de incompetência;"},{"letra":"C","texto":"caso reconheça o vício de incompetência, o magistrado deverá julgar extinto o feito, sem resolução do mérito;"},{"letra":"D","texto":"reputando configurado o vício de incompetência, o órgão do Ministério Público que intervier no feito poderá argui-lo;"},{"letra":"E","texto":"caso seja reconhecida a incompetência, a decisão concessiva da tutela provisória porventura proferida deverá ser anulada."}],"gabarito":"D","pct":"77,62"},{"id":"2694893","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Tutela Provisória (arts. 294 a 311)","enunciado":"Texto 1\n\nAlexandre, menor absolutamente incapaz, ajuizou ação pelo procedimento comum, representado por seu genitor, em face de operadora de plano de saúde, pleiteando a condenação desta a custear determinado tratamento cuja cobertura lhe fora negada, bem como a lhe pagar verba reparatória de danos morais.\n\nA petição inicial, na qual também foi requerida a concessão de tutela provisória para o fim de se assegurar, desde logo, a cobertura do tratamento, foi instruída com cópia do contrato celebrado com a operadora, com a documentação comprobatória dos pagamentos das mensalidades e com laudos médicos atestando a necessidade imediata do tratamento prescrito para o autor, além de outros documentos essenciais para a propositura da ação.\n\nA ação foi ajuizada em um juízo cível da Comarca de Goiânia, embora o menor e o seu representante legal residam em Serranópolis, tendo a operadora demandada, por sua vez, sede na cidade de São Paulo/SP, sem ter qualquer estabelecimento ou filial na capital goiana. Quanto ao contrato, foi ele entabulado no Município em que reside a parte autora.\n\nConsiderando a situação descrita no texto 1, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a tutela provisória requerida na petição inicial tem feição cautelar;"},{"letra":"B","texto":"a tutela provisória requerida na petição inicial tem feição satisfativa e de evidência;"},{"letra":"C","texto":"caso não aprecie o requerimento de tutela provisória, é lícito ao juiz analisá-lo e deferi-lo na sentença de mérito;"},{"letra":"D","texto":"o juiz deverá indeferir a tutela provisória requerida na petição inicial, diante do perigo de irreversibilidade dos efeitos de sua hipotética concessão;"},{"letra":"E","texto":"caso o autor tenha rotulado a tutela provisória requerida como cautelar, entendendo o juiz, contudo, que a sua natureza é de tutela antecipada, caber-lhe-á indeferir a medida."}],"gabarito":"C","pct":"63,19"},{"id":"2694896","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Civil","assunto":"Da Petição Inicial (arts. 319 a 331)","enunciado":"Cláudia intentou ação em face de Daniel, pleiteando a condenação deste a lhe pagar verbas indenizatórias em razão de ato ilícito que lhe atribuiu, consubstanciado na condução imprudente de veículo automotor, do que resultou um acidente que provocou lesões graves na autora.\n\nNa petição inicial, Cláudia formulou pedido genérico, alegando que não lhe era possível aferir todas as consequências do ato ilícito narrado, até porque ainda teria que se submeter a cirurgias por conta das lesões sofridas.\n\nApreciando a peça exordial, o juiz da causa ordenou a intimação da autora para emendá-la, a fim de formular pedido indenizatório determinado.\n\nCláudia, porém, alegou que a sua inicial não padecia de nenhum defeito, o que levou o juiz a indeferi-la, extinguindo o feito sem resolução do mérito. Inconformada, a demandante interpôs recurso de apelação.\n\nÉ correto afirmar, nesse cenário, que o recurso manejado pela parte autora:","alternativas":[{"letra":"A","texto":"comporta juízo de retratação, que, não sendo exercido, ensejará a remessa dos autos ao órgão ad quem, o qual deverá dar provimento ao apelo;"},{"letra":"B","texto":"não comporta juízo de retratação, o que ensejará a remessa dos autos ao órgão ad quem, o qual deverá dar provimento ao apelo;"},{"letra":"C","texto":"comporta juízo de retratação, que, não sendo exercido, ensejará a remessa dos autos ao órgão ad quem, o qual deverá negar provimento ao apelo;"},{"letra":"D","texto":"não comporta juízo de retratação, o que ensejará a remessa dos autos ao órgão ad quem, o qual deverá negar provimento ao apelo;"},{"letra":"E","texto":"não comporta juízo de retratação, o que ensejará a remessa dos autos ao órgão ad quem, o qual não deverá conhecer do apelo, à míngua de interesse recursal."}],"gabarito":"A","pct":"85,71"},{"id":"2120591","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Penal","assunto":"Dolo, Culpa e Preterdolo (arts. 18 e 19 do CP)","enunciado":"O agente que imagina já ter obtido o resultado pensado por ele, sem tê-lo alcançado, e, por isso, pratica outra conduta que efetivamente alcança o objetivo primário realiza a conduta em dolo","alternativas":[{"letra":"A","texto":"geral."},{"letra":"B","texto":"de segundo grau."},{"letra":"C","texto":"eventual."},{"letra":"D","texto":"alternativo."},{"letra":"E","texto":"cumulativo."}],"gabarito":"A","pct":"62,22"},{"id":"2120592","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Penal","assunto":"Do Furto (arts. 155 e 156 do CP)","enunciado":"Visando furtar uma residência, um indivíduo pulou o muro que a circunda e a invadiu. Antes de levar consigo os bens que já tinha separado na residência, ele ouviu o barulho de pessoas na calçada, que estavam suspeitando da ocorrência de algo errado na residência, motivo pelo qual fugiu do local, para não ser capturado.\n\n \nNessa situação hipotética, a conduta do indivíduo","alternativas":[{"letra":"A","texto":"configura furto qualificado tentado."},{"letra":"B","texto":"não configura nenhum crime, em razão da desistência voluntária."},{"letra":"C","texto":"configura furto simples tentado."},{"letra":"D","texto":"configura violação de domicílio na forma consumada."},{"letra":"E","texto":"configura furto simples tentado em concurso com a violação de domicílio na forma consumada."}],"gabarito":"A","pct":"56,75"},{"id":"2120594","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Penal","assunto":"Dolo, Culpa e Preterdolo (arts. 18 e 19 do CP)","enunciado":"Assinale a opção que indica a teoria segundo a qual a conduta é um movimento corporal voluntário, sem finalidade específica, que produz uma modificação no mundo exterior perceptível pelos sentidos.","alternativas":[{"letra":"A","texto":"teoria funcionalista radical"},{"letra":"B","texto":"teoria causalista"},{"letra":"C","texto":"teoria finalista"},{"letra":"D","texto":"teoria social da ação"},{"letra":"E","texto":"teoria funcionalista moderada"}],"gabarito":"B","pct":"66,93"},{"id":"2120595","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Penal","assunto":"Concurso de Crimes (arts. 69 a 76 do CP)","enunciado":"Considere que, ao praticar roubo em um ônibus, o agente tenha submetido ao ato três vítimas, uma sucessivamente à outra, encerrando toda a sua ação ao saltar pela janela do veículo. Nesse caso, houve","alternativas":[{"letra":"A","texto":"roubo na forma de crime continuado."},{"letra":"B","texto":"concurso material heterogêneo de crimes."},{"letra":"C","texto":"roubo na forma de crime único."},{"letra":"D","texto":"concurso material homogêneo de crimes."},{"letra":"E","texto":"concurso formal de crimes."}],"gabarito":"E","pct":"61,54"},{"id":"2120596","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Penal","assunto":"Dos Crimes contra a Honra (arts. 138 a 145 do CP)","enunciado":"Com relação aos crimes contra a honra, assinale a opção correta.","alternativas":[{"letra":"A","texto":"Admite-se a configuração de injúria contra pessoa jurídica."},{"letra":"B","texto":"A imunidade material dos vereadores pelos discursos que proferem restringe-se aos dizeres emanados por eles nos limites do município onde possuem mandato, além de ter estrita pertinência com o exercício do mandato."},{"letra":"C","texto":"A intenção de caçoar da vítima é suficiente para a configuração da difamação."},{"letra":"D","texto":"A imputação de um fato que não seja verdadeiro é pressuposto da difamação."},{"letra":"E","texto":"Tanto a calúnia quanto a difamação exigem resultado material."}],"gabarito":"B","pct":"68,21"},{"id":"2694939","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Dos Crimes contra a Liberdade Pessoal (arts. 146 a 149-A do CP)","enunciado":"Bianca, inconformada com o fim de seu namoro com Caio, ciente de que ele costuma frequentar determinado parque público para se exercitar aos domingos, passa a ir ao local, a fim de encontra-lo, ocasião em que, de forma insistente e aos prantos, pede para que reatem a relação amorosa, assim dificultando seu lazer, o que é feito em cinco domingos sucessivos.\n\nDiante do caso narrado, o crime cometido por Bianca é de:","alternativas":[{"letra":"A","texto":"perseguição;"},{"letra":"B","texto":"constrangimento ilegal;"},{"letra":"C","texto":"violência psicológica;"},{"letra":"D","texto":"importunação sexual;"},{"letra":"E","texto":"perturbação do sossego."}],"gabarito":"A","pct":"90,35"},{"id":"2694942","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Da Prescrição (arts. 108 a 119 do CP)","enunciado":"Ao arrolar as causas extintivas da punibilidade, o Código Penal prevê como uma delas a prescrição penal.\n\nSobre a citada figura jurídica, é correto afirmar que:","alternativas":[{"letra":"A","texto":"o curso do prazo da prescrição da pretensão punitiva interrompe-se pela reincidência;"},{"letra":"B","texto":"nos crimes permanentes, o prazo prescricional começa a correr do dia em que tem início a permanência;"},{"letra":"C","texto":"no caso de concurso formal de crimes, o prazo prescricional é calculado com base na pena aumentada pelo concurso;"},{"letra":"D","texto":"no cálculo do prazo prescricional, não se consideram causas de aumento ou de diminuição de pena;"},{"letra":"E","texto":"a publicação do acórdão condenatório, mesmo quando confirmatório da sentença de 1º grau, é causa interruptiva da prescrição."}],"gabarito":"E","pct":"61,55"},{"id":"2694944","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Dos Crimes contra a Liberdade Sexual e da Exposição da Intimidade Sexual (arts. 213 a 216-B do CP)","enunciado":"Dario, casado com Elisa, começa a beijá-la na cama, sendo correspondido. Na sequência, ele faz menção de terem relações sexuais, porém, ela recusa, alegando que está com sono e quer dormir. Não satisfeito com a negativa de Elisa, Dario a imobiliza e mantém com ela cópula vagínica, a força. Durante a relação sexual, diante da resistência de Elisa e da agressividade com que é possuída pelo marido, ela sofre lesões corporais leves.\n\nDiante do caso narrado, a correta adequação típica dos fatos, à luz do ordenamento jurídico penal, é:","alternativas":[{"letra":"A","texto":"lesão corporal qualificada pela violência doméstica;"},{"letra":"B","texto":"estupro qualificado por lesão corporal;"},{"letra":"C","texto":"estupro, com a pena aumentada;"},{"letra":"D","texto":"estupro e lesão corporal qualificada pela violência doméstica;"},{"letra":"E","texto":"estupro, com a pena aumentada, e lesão corporal qualificada pela violência doméstica."}],"gabarito":"C","pct":"54,74"},{"id":"2694948","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","enunciado":"Felisberto, réu em ação penal por crime de ameaça, cuja pena cominada é de detenção, de 1 a 6 meses, ou multa, é condenado ao final do processo. No curso da ação penal, restou demonstrado que o acusado é reincidente, pois possui condenação anterior definitiva por crime de ato obsceno, em que foi condenado à pena de multa, além de apresentar circunstâncias judiciais desfavoráveis.\n\nDiante do caso narrado, deverá o juiz aplicar, na sentença condenatória:","alternativas":[{"letra":"A","texto":"somente pena de multa;"},{"letra":"B","texto":"pena de detenção, em patamar superior ao mínimo legal cominado, com a fixação de regime inicialmente fechado;"},{"letra":"C","texto":"pena de detenção, em patamar superior ao mínimo legal cominado, com a fixação de regime inicialmente semiaberto;"},{"letra":"D","texto":"pena de detenção, no mínimo legal cominado, com a fixação de regime inicialmente aberto, concedendo ao réu a suspensão condicional da execução da pena;"},{"letra":"E","texto":"pena de detenção, em patamar superior ao mínimo legal cominado, com a fixação de regime inicialmente semiaberto, e a substituição da pena privativa de liberdade por uma pena restritiva de direitos ou multa."}],"gabarito":"C","pct":"50,98"},{"id":"2694954","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Do Furto (arts. 155 e 156 do CP)","enunciado":"Jorge, em agosto de 2023, invade o galinheiro de um vizinho, então ausente, de onde retira seis galinhas, duas das quais abate para sua alimentação, vendendo as demais, passando-se por seu dono. Jorge não possui qualquer anotação criminal e o valor total das referidas aves é de R$ 150,00.\n\nDiante do caso narrado, a correta adequação típica dos fatos, à luz do ordenamento jurídico penal, é:","alternativas":[{"letra":"A","texto":"furto privilegiado;"},{"letra":"B","texto":"furto qualificado;"},{"letra":"C","texto":"furto qualificado privilegiado;"},{"letra":"D","texto":"fato atípico, devendo ser reconhecido o princípio da bagatela;"},{"letra":"E","texto":"furto privilegiado e disposição de coisa alheia como própria."}],"gabarito":"C","pct":"33,71"},{"id":"2694955","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","enunciado":"Réu condenado, por sentença definitiva, pela prática de crime pode vir a não cumprir a pena ou a ter a execução da pena extinta, caso sobrevenha causa extintiva da punibilidade. Dentre essas causas, existem aquelas que, ocorridas após a sentença condenatória irrecorrível, extinguem todos os efeitos penais da condenação, principais e secundários.\n\nÉ o que acontece com o(a):","alternativas":[{"letra":"A","texto":"anistia;"},{"letra":"B","texto":"graça;"},{"letra":"C","texto":"indulto;"},{"letra":"D","texto":"prescrição da pretensão executória;"},{"letra":"E","texto":"reparação do dano, no crime de peculato culposo."}],"gabarito":"A","pct":"68,53"},{"id":"2694957","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Penal","assunto":"Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","enunciado":"Kátia, para evitar ser multada, modifica um dos algarismos da placa de seu automóvel. Certo dia, ao trafegar com o veículo nessa condição, Kátia é surpreendida por uma blitz da Polícia Militar, em atividade de policiamento ostensivo para prevenção e repressão de crimes, ocasião em que o agente lhe manda parar o automóvel, vindo ela a deixar de atendê-lo, seguindo com seu veículo.\n\nDiante do caso narrado, a correta adequação típica dos fatos, à luz do ordenamento jurídico penal, é:","alternativas":[{"letra":"A","texto":"fato atípico;"},{"letra":"B","texto":"desobediência;"},{"letra":"C","texto":"desobediência e evasão;"},{"letra":"D","texto":"adulteração de sinal identificador de veículo;"},{"letra":"E","texto":"desobediência e adulteração de sinal identificador de veículo."}],"gabarito":"E","pct":"73,00"},{"id":"2120622","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Processo Penal, seus Sistemas e Princípios","enunciado":"Em relação aos sistemas processuais penais e aos seus princípios reitores, assinale a opção correta.","alternativas":[{"letra":"A","texto":"A efetividade da repressão criminal do sistema acusatório cabe especialmente ao órgão julgador, responsável pela aplicação da pena no caso concreto."},{"letra":"B","texto":"No sistema acusatório, o legislador admite que a imparcialidade judicial esteja comprometida com um objetivo considerado mais importante."},{"letra":"C","texto":"O modelo ideal de sistema acusatório é previsto em instrumento normativo internacional, a partir de critérios uniformes definidos pela doutrina processual."},{"letra":"D","texto":"A crítica ao sistema inquisitivo está relacionada à sua falta de rigor quanto à certeza de repressão dos fatos contrários à ordem social."},{"letra":"E","texto":"A decisão sobre o sistema que deverá ser implantado em determinado país pressupõe uma definição prévia, por parte do legislador, de alguns critérios de política criminal, entre os quais está o grau de eficiência da repressão."}],"gabarito":"E","pct":"45,39"},{"id":"2120626","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Questões Mescladas sobre a Prova (arts. 155 a 250 do CPP)","enunciado":"No que diz respeito à prova no processo penal, assinale a opção correta.","alternativas":[{"letra":"A","texto":"O teor dos documentos particulares será submetido a exame pericial, quando contestada a sua veracidade."},{"letra":"B","texto":"A prova documental no processo penal deve ser produzida no momento próprio, sob pena de preclusão."},{"letra":"C","texto":"Caso tenha notícia da existência de documento relativo a ponto relevante da acusação ou da defesa, o juiz deverá providenciar, se possível, a sua juntada aos autos, independentemente de requerimento de qualquer das partes."},{"letra":"D","texto":"Os documentos originais juntados a processo findo poderão ser entregues à parte que os produziu, independentemente de traslado, quando não existir motivo relevante que justifique a sua conservação nos autos."},{"letra":"E","texto":"As cartas particulares poderão ser exibidas em juízo pelo respectivo destinatário, para a defesa de seu direito, desde que mediante consentimento do signatário."}],"gabarito":"C","pct":"49,95"},{"id":"2120627","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Da Prisão Domiciliar (arts. 317 e 318 do CPP)","enunciado":"De acordo com o Código de Processo Penal, preenchidas as condições legais e apresentada prova idônea, o juiz poderá substituir a prisão preventiva pela domiciliar quando o agente for","alternativas":[{"letra":"A","texto":"maior de 70 anos."},{"letra":"B","texto":"imprescindível aos cuidados especiais de pessoa menor de 8 anos."},{"letra":"C","texto":"agente de força de segurança, salvo se a infração envolver violação de dever funcional ou violência."},{"letra":"D","texto":"gestante, independentemente do estágio da gravidez."},{"letra":"E","texto":"homem, caso seja o único responsável pelos cuidados de filho de até 14 anos de idade incompletos."}],"gabarito":"D","pct":"80,18"},{"id":"2120630","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Fase Instrutória (arts. 399 a 405 do CPP)","enunciado":"Considerando as disposições do Código de Processo Penal relativas à audiência de instrução e julgamento no procedimento comum ordinário, assinale a opção correta.","alternativas":[{"letra":"A","texto":"A inquirição das testemunhas de acusação precede a das testemunhas de defesa e a tomada de declarações do ofendido."},{"letra":"B","texto":"Produzidas todas as provas em audiência, as partes poderão requerer diligências ensejadas por fatos apurados na instrução no prazo máximo de 24 horas."},{"letra":"C","texto":"Poderão ser inquiridas até oito testemunhas da defesa e oito da acusação, não devendo ser computadas nesse número as que não prestem compromisso e as que tenham sido referidas."},{"letra":"D","texto":"A parte poderá desistir da inquirição de qualquer das testemunhas arroladas, desde que a outra parte concorde."},{"letra":"E","texto":"Caso não haja requerimento de diligências ou caso este seja indeferido, serão oferecidas alegações finais, pela acusação, pelo prazo de 10 minutos, tendo a defesa idêntico período para apresentar seus argumentos."}],"gabarito":"C","pct":"72,40"},{"id":"2120632","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Procedimento dos Crimes da Competência do Tribunal do Júri (arts. 406 a 497 do CPP)","enunciado":"O Ministério Público ofereceu denúncia contra João e Francisco, imputando-lhes a prática do crime de homicídio qualificado por motivo fútil. Após a pronúncia, eles foram submetidos a julgamento pelo tribunal do júri. Nessa situação hipotética,","alternativas":[{"letra":"A","texto":"o conselho de sentença formado para o julgamento de João e Francisco poderá conhecer de outro processo no mesmo dia, desde que haja aceitação das partes e seja prestado novo compromisso."},{"letra":"B","texto":"o conselho de sentença deverá responder a quesito sobre agravantes e atenuantes sustentadas em plenário após o reconhecimento d a materialidade e da autoria do fato, bem como da incidência de circunstância qualificadora."},{"letra":"C","texto":"a separação dos julgamentos deverá ser feita se, devido a recusas, não for possível compor o conselho de sentença com o mínimo de sete jurados, situação em que o acusado mais velho deverá ser julgado primeiro, a fim de minimizar o risco de prescrição."},{"letra":"D","texto":"o Ministério Público terá, nos debates, o prazo máximo de uma hora e meia para sustentar a acusação, e a defesa disporá do mesmo tempo para expor as suas teses."},{"letra":"E","texto":"ao membro do Ministério Público são vedadas, durante os debates, a leitura de jornais ou a exibição de vídeos, com a finalidade de convencer os jurados da tese acusatória."}],"gabarito":"A","pct":"51,66"},{"id":"2120638","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Processual Penal","assunto":"Fase Decisória e Sentença Penal (arts. 381 a 392 do CPP)","enunciado":"Felipe, maior de 21 anos de idade, primário e sem antecedentes, foi condenado a cumprir pena de 4 anos e 8 meses de reclusão em regime inicial semiaberto, em razão da prática do crime de roubo simples. Durante a ação penal, ele permaneceu preso preventivamente por 6 meses.\n\n \nNessa situação hipotética, conforme a jurisprudência do Superior Tribunal de Justiça, caso o tempo de prisão não tenha sido considerado para a definição do regime inicial,","alternativas":[{"letra":"A","texto":"não haverá vício na sentença, já que o tempo de custódia cautelar não seria suficiente para autorizar a progressão ao regime aberto."},{"letra":"B","texto":"não haverá vício na sentença, uma vez que o tempo de custódia cautelar deverá ser examinado pelo juízo da execução para fins de definição do regime inicial."},{"letra":"C","texto":"haverá vício na sentença, uma vez que o tempo de custódia cautelar seria suficiente para autorizar a progressão ao regime aberto."},{"letra":"D","texto":"haverá vício na sentença, haja vista que o tempo de custódia cautelar seria suficiente para o estabelecimento do regime inicial aberto."},{"letra":"E","texto":"não haverá vício na sentença, já que o tempo de custódia cautelar seria insuficiente para o estabelecimento do regime inicial aberto."}],"gabarito":"E","pct":"45,88"},{"id":"2694950","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Jurisprudência dos Tribunais Superiores sobre Assuntos Diversos ou Mesclados de Processo Penal","enunciado":"Homero, sócio-gerente de um pequeno restaurante, que atravessa grave crise financeira em decorrência da pandemia, pela redução expressiva de seu número de clientes, deixa de recolher aos cofres públicos, no prazo legal, valores relativos ao Imposto sobre Circulação de Mercadorias e Serviços (ICMS), vindo a ser processado criminalmente pelos fatos.\n\nDiante do caso narrado e à luz da jurisprudência do STJ sobre o tema, é correto afirmar que:","alternativas":[{"letra":"A","texto":"Homero não cometeu qualquer crime, pois os fatos constituem prática de elisão fiscal, devendo o juiz absolvê-lo;"},{"letra":"B","texto":"deve ser reconhecido, em favor de Homero, que praticou o fato quando não lhe era exigível conduta diversa, sendo cabível sua absolvição;"},{"letra":"C","texto":"Homero não cometeu qualquer crime, pois, em consideração às circunstâncias em que agiu, deve ser reconhecida a ausência de dolo em sua conduta, cabendo ao juiz absolvê-lo;"},{"letra":"D","texto":"deve ser reconhecido, em favor de Homero, que praticou o fato sob estado de necessidade, com sua consequente absolvição;"},{"letra":"E","texto":"Homero cometeu o crime de apropriação indébita tributária, inexistindo qualquer excludente da ilicitude ou eximente da culpabilidade que possa beneficiá-lo, devendo o juiz condená-lo."}],"gabarito":"B","pct":"42,22"},{"id":"2694958","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Da Ação Penal (arts. 24 a 62 do CPP)","enunciado":"Em crime de roubo praticado por Orestes, no qual Saulo figurou como ofendido, o Ministério Público, ao fim da investigação, não ofereceu denúncia tampouco se manifestou no prazo legal. Diante disso, Saulo, por intermédio de seu advogado, ajuizou ação privada subsidiária da pública, a qual foi recebida pelo juízo. Contudo, no curso do feito, Saulo, apesar de devidamente intimado por três vezes, deixou de promover o andamento do processo por seis meses seguidos.\n\nNessa hipótese, é correto afirmar que deverá:","alternativas":[{"letra":"A","texto":"o juiz declarar a ocorrência da perempção e a consequente extinção da punibilidade de Orestes;"},{"letra":"B","texto":"o Ministério Público requerer a extinção do feito em razão da decadência do direito de queixa de Saulo;"},{"letra":"C","texto":"o juiz declarar a ocorrência da renúncia tácita de Saulo e a consequente extinção da punibilidade de Orestes;"},{"letra":"D","texto":"o Ministério Público retomar a ação como parte principal em razão da negligência de Saulo;"},{"letra":"E","texto":"o juiz declarar a ocorrência do perdão tácito de Saulo e a consequente extinção da punibilidade de Orestes."}],"gabarito":"D","pct":"80,03"},{"id":"2694961","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Questões Mescladas sobre a Prova (arts. 155 a 250 do CPP)","enunciado":"O Ministério Público, em processo movido em face de Frederico pelo crime de extorsão mediante sequestro, requereu a juntada aos autos, como prova documental, de trechos de transcrições de conversas resultantes de interceptação telefônica constantes de outro processo em que Frederico responde pelo crime de tráfico ilícito de entorpecentes. Porém, tais interceptações telefônicas, que incriminavam Frederico quanto aos crimes de tráfico e de extorsão mediante sequestro, foram realizadas sem autorização judicial.\n\nDiante desse cenário, e considerando o requerimento de juntada do Ministério Público, é correto afirmar que a prova:","alternativas":[{"letra":"A","texto":"não poderá ser juntada aos autos, pois originariamente ilícita e, portanto, inadmissível no processo;"},{"letra":"B","texto":"poderá ser juntada aos autos, pois se trata de prova emprestada, produzida entre as mesmas partes e perante o mesmo juízo;"},{"letra":"C","texto":"não poderá ser juntada aos autos, a não ser que com ela concorde a defesa técnica de Frederico, e mediante decisão judicial;"},{"letra":"D","texto":"poderá ser juntada aos autos como documento, diante do princípio da comunhão das provas, em qualquer fase do processo;"},{"letra":"E","texto":"poderá ser juntada aos autos, diante de autorização judicial superveniente suprindo a falta da anterior decisão judicial permitindo a interceptação."}],"gabarito":"A","pct":"91,52"},{"id":"2694963","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Demais Tópicos Processuais Penais e Questões Variadas","enunciado":"No que diz respeito ao ofendido e às suas prerrogativas no processo penal brasileiro, é correto afirmar que poderá:","alternativas":[{"letra":"A","texto":"interpor recurso de apelação, ainda que não habilitado como assistente, quando o Ministério Público tiver recorrido de todo o conteúdo impugnável da sentença;"},{"letra":"B","texto":"o juiz determinar o segredo de justiça em relação a dados e depoimentos constantes dos autos a respeito do ofendido para evitar sua exposição aos meios de comunicação;"},{"letra":"C","texto":"se habilitar como assistente de acusação, no curso da investigação criminal, com a anuência prévia do Ministério Público;"},{"letra":"D","texto":"requerer ao juiz a prisão temporária do investigado caso este ameace a sua integridade física durante a investigação criminal;"},{"letra":"E","texto":"requisitar a instauração de inquérito policial e a realização de diligências investigatórias que deverão ser realizadas pela autoridade policial."}],"gabarito":"B","pct":"67,05"},{"id":"2694965","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Das Medidas Assecuratórias (arts. 125 a 144 do CPP)","enunciado":"Henrique, investigado em razão da prática de vultoso crime de estelionato cometido contra Enéas, possui em seu patrimônio bens suficientes para assegurar a reparação do dano causado ao ofendido.\n\nNesse contexto, é correto afirmar que poderá:","alternativas":[{"letra":"A","texto":"o ofendido Enéas requerer ao juiz a busca e apreensão dos bens constantes do patrimônio de Henrique;"},{"letra":"B","texto":"o ofendido Enéas requerer cautelarmente a perda alargada dos bens constantes do patrimônio de Henrique;"},{"letra":"C","texto":"o ofendido Enéas requerer ao juiz a decretação do sequestro dos bens constantes do patrimônio de Henrique;"},{"letra":"D","texto":"o Ministério Público requerer ao juiz o sequestro alargado dos bens constantes do patrimônio de Henrique;"},{"letra":"E","texto":"o juiz de ofício decretar cautelarmente a perda alargada dos bens constantes do patrimônio de Henrique."}],"gabarito":"C","pct":"73,99"},{"id":"2694967","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Procedimento dos Crimes da Competência do Tribunal do Júri (arts. 406 a 497 do CPP)","enunciado":"Relativamente às regras e ao procedimento para o julgamento dos crimes dolosos contra a vida no Tribunal do Júri, é correto afirmar que:","alternativas":[{"letra":"A","texto":"os jurados, em razão da incomunicabilidade, não poderão formular perguntas ao acusado, ao ofendido e às testemunhas;"},{"letra":"B","texto":"nos debates, a defesa poderá ir à réplica e a acusação ir à tréplica, sendo possível a reinquirição de testemunhas já ouvidas;"},{"letra":"C","texto":"a acusação poderá fazer referência ao silêncio do acusado como argumento de autoridade em prejuízo deste, sem que isso implique nulidade;"},{"letra":"D","texto":"durante o julgamento não será permitida a leitura de documento que não tiver sido juntado aos autos com a antecedência de três dias úteis, dando-se ciência à outra parte;"},{"letra":"E","texto":"para a inquirição das testemunhas arroladas pela defesa, o defensor do acusado formulará as perguntas após o Ministério Público e o assistente."}],"gabarito":"D","pct":"78,71"},{"id":"2694970","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Da Ação Civil Ex Delicto (arts. 63 a 68 do CPP)","enunciado":"Apesar de o Ministério Público ter opinado pela condenação de Marlon, em processo em face deste promovido em razão da prática do crime de roubo contra Robson, o juiz absolveu o acusado ao fundamento de estar provada a inexistência do fato criminoso.\n\nNesse contexto, é correto afirmar que:","alternativas":[{"letra":"A","texto":"poderá o juiz fixar na sentença valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido;"},{"letra":"B","texto":"poderá o ofendido interpor recurso de apelação em face da absolvição se o Ministério Público recorrer de todo o conteúdo impugnável da sentença;"},{"letra":"C","texto":"vinculará o juízo cível, para efeito de impedir a reparação do dano causado ao ofendido, uma vez transitada em julgado a absolvição;"},{"letra":"D","texto":"poderá o juiz decretar na sentença o sequestro dos bens de Marlon com vistas à reparação dos danos causados ao ofendido;"},{"letra":"E","texto":"vinculará o juízo cível, para efeito de impedir a reparação do dano causado ao ofendido, caso em via recursal se reconheça que o fato não constitui crime."}],"gabarito":"C","pct":"63,23"},{"id":"2694972","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Habeas Corpus (arts. 647 a 667 do CPP)","enunciado":"No tocante às ações autônomas de impugnação no processo penal brasileiro, mais especificamente à revisão criminal e ao habeas corpus, é correto afirmar que:","alternativas":[{"letra":"A","texto":"no habeas corpus impetrado por outra pessoa que não o paciente, deverá a petição ser assinada por advogado e serão recolhidas as custas processuais;"},{"letra":"B","texto":"na revisão criminal, o prazo para o seu ajuizamento será de vinte anos contados do trânsito em julgado da sentença condenatória;"},{"letra":"C","texto":"no habeas corpus impetrado pelo Ministério Público em favor do acusado, deve a causa de pedir se referir a crime cuja ação é de iniciativa pública;"},{"letra":"D","texto":"na revisão criminal fará jus à indenização o condenado se o erro ou a injustiça da condenação proceder de ato ou falta imputável ao próprio impetrante;"},{"letra":"E","texto":"no habeas corpus, ordenada a soltura do paciente, será condenada nas custas a autoridade que, por má-fé ou evidente abuso de poder, tiver determinado a coação."}],"gabarito":"E","pct":"81,78"},{"id":"2694974","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Processual Penal","assunto":"Questões Mescladas sobre Recursos (Processo Penal)","enunciado":"No que diz respeito à teoria geral e às regras que regem os recursos no processo penal brasileiro, é correto afirmar que:","alternativas":[{"letra":"A","texto":"caberá recurso em sentido estrito em face da decisão judicial que concluir pela competência do juízo criminal para conhecer da causa;"},{"letra":"B","texto":"caberá recurso de apelação em face da decisão judicial que recusar homologação à proposta de acordo de não persecução penal;"},{"letra":"C","texto":"por força da fungibilidade recursal, quando for cabível a apelação, poderá ser usado o recurso em sentido estrito, ainda que somente se recorra de parte da decisão;"},{"letra":"D","texto":"o Ministério Público poderá renunciar ao recurso, bem como desistir do recurso que haja interposto nos crimes cuja ação seja pública incondicionada;"},{"letra":"E","texto":"no concurso de agentes, a decisão do recurso interposto por um dos réus, se fundado em motivos que não sejam de caráter exclusivamente pessoal, aproveitará aos outros."}],"gabarito":"E","pct":"88,79"},{"id":"2120648","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Constitucionalismo e Neoconstitucionalismo","enunciado":"No tocante ao neoconstitucionalismo, ao conceito de Constituição e às normas constitucionais, assinale a opção correta.","alternativas":[{"letra":"A","texto":"O neoconstitucionalismo está associado a diversos fenômenos reciprocamente implicados, seja no campo empírico, seja no plano da dogmática jurídica, como reconhecimento da força normativa dos princípios jurídicos e da separação entre o direito e a moral."},{"letra":"B","texto":"A Constituição Federal de 1988 é considerada exemplo típico de constituição compromissória, uma vez que, na constituinte, houve a atuação das mais diversas forças políticas, inspiradas em diferentes ideologias."},{"letra":"C","texto":"Nas constituições flexíveis, o conflito entre a norma constitucional anterior e a lei superveniente resolve-se não pelo critério hierárquico, mas pelo critério de especialidade."},{"letra":"D","texto":"Prevalece a adoção da teoria da dupla revisão no sistema constitucional brasileiro."},{"letra":"E","texto":"No sentido sociológico, a constituição é entendida como a decisão política fundamental do titular do poder constituinte."}],"gabarito":"B","pct":"49,22"},{"id":"2120655","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Questões Mescladas de Organização do Estado (arts. 18 a 43 da CF/1988)","enunciado":"A respeito da organização político-administrativa do Estado brasileiro, assinale a opção correta.","alternativas":[{"letra":"A","texto":"A formação da Federação brasileira resultou de um movimento centrípeto, de fora para dentro, a partir da união de vários Estados soberanos."},{"letra":"B","texto":"É inconstitucional lei estadual que autorize a comercialização de bebidas alcoólicas em eventos esportivos, pois tal medida invade a competência da União para o estabelecimento de normas gerais sobre consumo e desporto."},{"letra":"C","texto":"Constituição estadual pode prever hipóteses de intervenção estadual diferentes daquelas que são previstas no art. 35 da Constituição Federal de 1988, uma vez que o rol estabelecido na Carta Magna é exemplificativo."},{"letra":"D","texto":"É inconstitucional lei estadual que obrigue a divulgação, em jornais e programas televisivos, de fotos de crianças desaparecidas."},{"letra":"E","texto":"É constitucional lei estadual que proíba que os prestadores de serviço público de abastecimento de água e de esgotamento sanitário inscrevam os usuários inadimplentes no SPC/SERASA."}],"gabarito":"D","pct":"63,10"},{"id":"2120658","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Questões Mescladas de Organização dos Poderes (arts. 44 a 135 da CF/1988)","enunciado":"Acerca dos poderes da República, assinale a opção correta.","alternativas":[{"letra":"A","texto":"Governador pode ser obrigado a depor em Comissão Parlamentar de Inquérito instaurada no Congresso Nacional, desde que a finalidade seja tratar de fatos que afetem o interesse da União."},{"letra":"B","texto":"A imposição a parlamentares municipais de medidas cautelares de afastamento de suas funções legislativas por determinação de juiz de primeiro grau condiciona-se à prévia deliberação da câmara de vereadores competente."},{"letra":"C","texto":"Compete à justiça federal de primeiro grau, e não ao Supremo Tribunal Federal, julgar ações ordinárias para impugnar atos do Conselho Nacional de Justiça."},{"letra":"D","texto":"É necessária prévia autorização da assembleia legislativa do estado para que governador de estado seja processado por crime comum no Superior Tribunal de Justiça."},{"letra":"E","texto":"Em caso de nova legislatura, é possível a recondução dos presidentes da Câmara dos Deputados e do Senado Federal para o mesmo cargo na eleição imediatamente subsequente."}],"gabarito":"E","pct":"58,33"},{"id":"2120661","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Estado de Defesa e de Sítio (arts. 136 a 141 da CF/1988)","enunciado":"A respeito do sistema constitucional de crises e da defesa do Estado e das instituições democráticas, assinale a opção correta.","alternativas":[{"letra":"A","texto":"As imunidades de deputados ou senadores serão suspensas durante o estado de sítio, dada a excepcionalidade da medida."},{"letra":"B","texto":"No estado de sítio, é constitucional a determinação, pelo presidente da República, de restrição à liberdade de imprensa, radiodifusão e televisão."},{"letra":"C","texto":"O estado de defesa somente poderá ser decretado após voto da maioria absoluta do Congresso Nacional."},{"letra":"D","texto":"O estado de defesa pode ser deflagrado em resposta a agressão armada estrangeira."},{"letra":"E","texto":"Durante o estado de defesa, a prisão ou detenção de qualquer pessoa não poderá ultrapassar quinze dias, salvo quando autorizada pelo Poder Judiciário."}],"gabarito":"B","pct":"78,81"},{"id":"2120667","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Controle de Constitucionalidade","enunciado":"Em relação ao controle de constitucionalidade, à súmula vinculante e à jurisprudência do Supremo Tribunal Federal, assinale a opção correta.","alternativas":[{"letra":"A","texto":"A arguição de descumprimento de preceito fundamental (ADPF) não é instrumento eficaz de controle da inconstitucionalidade por omissão."},{"letra":"B","texto":"O efeito vinculante em ação direta de inconstitucionalidade (ADI) e em ação declaratória de constitucionalidade (ADC) não atinge o Poder Legislativo no exercício de sua função típica de legislar, em observância à proibição de fossilização constitucional."},{"letra":"C","texto":"O defensor público-geral da União não tem legitimidade para propor nem ação direta de inconstitucionalidade (ADI), nem a edição, a revisão ou o cancelamento de súmula vinculante."},{"letra":"D","texto":"Exige-se a observância da cláusula de reserva de plenário nas hipóteses em que o tribunal decida pela não recepção de determinada norma pré-constitucional."},{"letra":"E","texto":"Não cabe ação direta de inconstitucionalidade (ADI) contra lei que viole a Convenção Internacional sobre os Direitos das Pessoas com Deficiência, por esta possuir status normativo supralegal."}],"gabarito":"B","pct":"81,95"},{"id":"2120669","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Sistema Tributário Nacional","enunciado":"De acordo com a Constituição Federal de 1988 e a jurisprudência do Supremo Tribunal Federal acerca da ordem econômica e financeira, das finanças públicas, bem como do Sistema Tributário Nacional, assinale a opção correta.","alternativas":[{"letra":"A","texto":"A imunidade tributária cultural aplica-se à importação e comercialização, no mercado interno, dos livros eletrônicos (e-books) e dos suportes exclusivamente utilizados para fixá-los, como leitores de livros eletrônicos (e-readers), ainda que possuam funcionalidades acessórias."},{"letra":"B","texto":"As alíquotas máximas do imposto sobre transmissão causa mortis e doação de quaisquer bens ou direitos (ITCD) são fixadas por lei complementar."},{"letra":"C","texto":"A competência da União para emitir moeda é exercida pela Caixa Econômica Federal ou pelo Banco do Brasil."},{"letra":"D","texto":"O aproveitamento do potencial de energia renovável, de capacidade reduzida ou não, dependerá de autorização ou concessão do poder público."},{"letra":"E","texto":"É inconstitucional a adoção, no cálculo do valor de taxa, de um ou mais elementos da base de cálculo própria de determinado imposto, desde que não haja integral identidade entre uma base e outra."}],"gabarito":"A","pct":"80,70"},{"id":"2694983","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Disposições Gerais (Administração Pública - arts. 37 e 38 da CF/1988)","enunciado":"Em determinada situação fática já constituída no âmbito do Estado Delta, João se aposentou no cargo de promotor de Justiça e, após regular aprovação em concurso público de provas e títulos, tomou posse no cargo de juiz de direito.\n\nÀ luz dessa narrativa, é correto afirmar, consoante a sistemática inaugurada com a Constituição de 1988 e suas sucessivas alterações, que a posse no segundo cargo:","alternativas":[{"letra":"A","texto":"somente passou a ser considerada incompatível com a ordem constitucional com a publicação da Emenda Constitucional nº 20/1998, que vedou, em qualquer hipótese ou momento, a acumulação realizada por João;"},{"letra":"B","texto":"era expressamente admitida pela Constituição da República, mas a soma dos proventos de aposentadoria de João, após se aposentar como juiz de direito, não poderia ultrapassar o teto remuneratório constitucional;"},{"letra":"C","texto":"sempre foi considerada incompatível com a Constituição da República e suas reformas, independentemente do momento em que os fatos ocorreram, sendo nula de pleno direito, considerando a impossibilidade de os cargos serem acumulados na atividade;"},{"letra":"D","texto":"foi admitida pela Emenda Constitucional nº 20/1998, isto em relação à situação jurídica daqueles que, como João, se aposentaram e retornaram ao serviço público até a sua publicação, mas lhes seria vedado receber mais de uma aposentadoria pelo regime próprio;"},{"letra":"E","texto":"embora fosse vedada pela Constituição da República, a promulgação da Emenda Constitucional nº 20/1998 assegurou o respeito ao direito adquirido e a percepção dos proventos de aposentadoria correspondentes a ambos os cargos, desde que a situação estivesse consolidada, o que poderia alcançar João."}],"gabarito":"D","pct":"41,99"},{"id":"2694985","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Organização, Competências e Bens dos Entes Federativos","enunciado":"A sociedade empresária Sigma explorava a atividade de transmissão e recepção de dados e voz, por meio de torres e antenas situadas no território do Município Beta. Em razão da atividade desenvolvida em solo municipal, esse ente federativo editou a Lei nº X, instituindo a taxa de funcionamento das respectivas estações, com estrita observância das denominadas “limitações constitucionais ao poder de tributar”.\n\nÀ luz da ordem constitucional, é correto afirmar que a Lei nº X é:","alternativas":[{"letra":"A","texto":"inconstitucional, considerando a natureza da atividade explorada por Sigma, o que afasta a competência de Beta para instituir a referida taxa;"},{"letra":"B","texto":"constitucional, considerando que Beta tem competência para suplementar a legislação federal e a estadual, de modo a atender às peculiaridades locais;"},{"letra":"C","texto":"constitucional, considerando que a ocupação do solo urbano é típico interesse local, a justificar a competência legislativa privativa de Beta para instituir a taxa;"},{"letra":"D","texto":"inconstitucional, considerando que as atividades já exploradas, com contribuintes previamente identificados, não configuram fato gerador da taxa, face à ausência de serviço público específico e divisível;"},{"letra":"E","texto":"constitucional, considerando se tratar de matéria com nítidos reflexos no meio ambiente, em que prevalece a competência concorrente entre os entes federativos, observados os balizamentos estabelecidos pela União."}],"gabarito":"A","pct":"74,66"},{"id":"2694990","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Controle de Constitucionalidade","enunciado":"A sociedade empresária Alfa ingressou com ação ordinária em face do Estado Beta, visando a desconstituir crédito tributário relativo ao Imposto sobre Circulação de Mercadorias e Serviços (ICMS), desonerando-a igualmente de recolhimentos futuros. O argumento era o de que a Lei nº X, utilizada pelo fisco para constituir o crédito, apresentava vício de inconstitucionalidade. Alfa obteve êxito em sua pretensão, inclusive com o reconhecimento, em sede incidental, pelo Órgão Especial do Tribunal de Justiça do Estado Beta, de que o referido diploma normativo era incompatível com a Constituição da República. Três anos após o trânsito em julgado do acórdão favorável a Alfa, o Supremo Tribunal Federal (STF) reconheceu a constitucionalidade da Lei nº X.\n\nNesse caso, à luz da sistemática vigente, é correto afirmar que:","alternativas":[{"letra":"A","texto":"Alfa está amparada pelos efeitos da coisa julgada, logo, o reconhecimento posterior da constitucionalidade da Lei nº X pelo STF não produz efeitos em relação a ela, quer esse reconhecimento tenha ocorrido em sede de controle concentrado, quer em controle difuso;"},{"letra":"B","texto":"caso o STF tenha reconhecido a constitucionalidade da Lei nº X em sede de controle difuso ou concentrado, essa decisão somente irá se sobrepor à coisa julgada que se formou em favor de Alfa com o manejo da ação rescisória, produzindo efeitos a partir da decisão favorável obtida pelo fisco nesta última;"},{"letra":"C","texto":"caso o STF tenha reconhecido a constitucionalidade da Lei nº X em sede de controle concentrado, essa decisão se sobrepõe automaticamente à coisa julgada que se formou em favor de Alfa, autorizando que o Estado Beta cobre todos os créditos devidos por esta sociedade empresária, anteriores e posteriores à referida decisão;"},{"letra":"D","texto":"caso o STF tenha reconhecido a constitucionalidade da Lei nº X em sede de controle difuso, com repercussão geral reconhecida, serão automaticamente interrompidos os efeitos da coisa julgada formada em favor de Alfa, mas isto apenas para o futuro, observadas, ainda, as limitações constitucionais ao poder de tributar;"},{"letra":"E","texto":"caso o STF tenha reconhecido a constitucionalidade da Lei nº X em sede de controle difuso, ainda que sem repercussão geral, essa decisão se sobrepõe automaticamente à coisa julgada que se formou em favor de Alfa, de modo que o Estado Beta cobre os créditos devidos por esta sociedade empresária, constituídos em momento anterior à decisão."}],"gabarito":"D","pct":"54,99"},{"id":"2694994","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Direitos Sociais e dos Trabalhadores","enunciado":"João, solteiro convicto, tinha o sonho de ser pai. Com esse objetivo, procurou uma clínica especializada no exterior e realizou a técnica de fertilização in vitro. A gestação por substituição, por sua vez, foi realizada por Marie, pessoa com a qual João não mantinha qualquer relação afetiva. Logo após o parto, a criança XX foi entregue a João, que retornou ao território brasileiro e a registrou apenas em seu nome.\n\nComo João é servidor público, requereu ao Departamento de Recursos Humanos da repartição pública a fruição de licença-maternidade, considerando o ônus que assumiria, de cuidar, sozinho, de XX.\n\nAo analisar a ordem constitucional, a autoridade competente explicou corretamente a João que ele:","alternativas":[{"letra":"A","texto":"não faz jus à referida licença, pois não poderia ser equiparado à mãe na medida em que XX possuía mãe conhecida;"},{"letra":"B","texto":"faz jus à licença-maternidade, desde que seja demonstrado que Marie não requereu a fruição de benefício similar no exterior;"},{"letra":"C","texto":"não faz jus à licença-maternidade, pois a igualdade entre homens e mulheres é excepcionada pelas situações previstas na ordem constitucional;"},{"letra":"D","texto":"somente faria jus à licença-maternidade caso a legislação expressamente o autorizasse, o que decorria do princípio da legalidade estrita que deve reger a Administração Pública;"},{"letra":"E","texto":"faz jus à licença-maternidade, considerando que XX deve ser protegida com absoluta prioridade, além de os direitos sociais da mulher também se destinarem à proteção da criança."}],"gabarito":"E","pct":"88,42"},{"id":"2694996","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Organização Político-Administrativa","enunciado":"O Tribunal de Contas do Estado de Goiás recebeu, para apreciação, as contas de gestão apresentadas pelo prefeito do Município Alfa. Após avaliação do corpo técnico e detida análise dos conselheiros, concluiu, corretamente, que parte das despesas alegadamente realizadas não foi comprovada, havendo provas insofismáveis de desvio de recursos públicos.\n\nNesse caso, à luz da sistemática vigente, o Tribunal de Contas do Estado de Goiás deve:","alternativas":[{"letra":"A","texto":"emitir parecer prévio, não julgar as contas do prefeito, munus da Câmara Municipal de Alfa, desde que o ilícito praticado tenha correlação com as contas de governo;"},{"letra":"B","texto":"julgar as contas do prefeito de Alfa, sendo que o Município Alfa é o único legitimado para a execução da multa que venha a ser aplicada e para o ressarcimento dos danos;"},{"letra":"C","texto":"emitir parecer prévio, não julgar as contas do prefeito, o qual será vinculante para a Câmara Municipal de Alfa caso seja demonstrada a prática de ato doloso de improbidade;"},{"letra":"D","texto":"emitir parecer prévio, não julgar as contas do prefeito, munus da Câmara Municipal de Alfa, que somente poderá deixar de acolher o referido parecer por decisão de dois terços dos vereadores;"},{"letra":"E","texto":"julgar as contas do prefeito de Alfa, sendo que o Município Alfa é o único legitimado para requerer em juízo o ressarcimento dos danos, enquanto o Estado de Goiás deve executar a multa que venha a ser aplicada."}],"gabarito":"D","pct":"78,32"},{"id":"2694997","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Educação, Cultura e Desporto","enunciado":"Maria, moradora do Município Alfa, não conseguiu efetuar a matrícula do filho de 2 anos em estabelecimento de educação infantil municipal próximo de sua residência. Ao questionar o motivo da impossibilidade, o Município alegou que a rede municipal não tinha vaga para crianças da idade de seu filho, já que não havia legislação municipal que fornecesse tal garantia. Diante do exposto e da jurisprudência do Supremo Tribunal Federal, é correto afirmar que:","alternativas":[{"letra":"A","texto":"a municipalidade não tem o dever de efetuar a matrícula do filho de Maria, pois às crianças entre 0 e 5 anos de idade o atendimento em creche e pré-escola não é obrigatório e necessita de regulamentação pelo Poder Legislativo;"},{"letra":"B","texto":"Maria não poderá exigir judicialmente do Município a matrícula de seu filho na escola municipal, pois a norma que garante a concretização desse direito fundamental é de eficácia contida sem aplicabilidade imediata;"},{"letra":"C","texto":"o Município Alfa tem o dever constitucional de assegurar ao filho de Maria o atendimento em creche e pré-escola. A educação infantil é direito subjetivo assegurado no próprio texto constitucional, mediante norma de aplicabilidade direta e eficácia plena;"},{"letra":"D","texto":"o Município Alfa não tem o dever constitucional de assegurar ao filho de Maria o atendimento em creche e pré-escola. A educação infantil não é direito subjetivo, pois é norma programática e depende de implementação pelo poder público;"},{"letra":"E","texto":"o Município Alfa tem o dever de assegurar ao filho de Maria o atendimento em pré-escola (4 a 5 anos), mas não em creche (0 a 3 anos), pois apenas a educação básica é direito subjetivo previsto na Constituição."}],"gabarito":"C","pct":"92,90"},{"id":"2694998","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Disposições Gerais do Poder Judiciário","enunciado":"Determinada Lei do Estado Beta prevê a adoção do maior tempo de serviço público como critério de desempate para a promoção na carreira da magistratura estadual.\n\nDiante do exposto e da jurisprudência do Supremo Tribunal Federal, é correto afirmar que a referida norma é:","alternativas":[{"letra":"A","texto":"inconstitucional, pois compete à União, mediante lei complementar de iniciativa reservada ao presidente da República, legislar sobre a organização da magistratura nacional;"},{"letra":"B","texto":"constitucional, pois compete ao Estado, mediante lei complementar de iniciativa reservada ao presidente do Tribunal de Justiça local, legislar sobre a organização da magistratura estadual;"},{"letra":"C","texto":"inconstitucional, pois compete à União, mediante lei complementar de iniciativa reservada ao Supremo Tribunal Federal, legislar sobre a organização da magistratura nacional;"},{"letra":"D","texto":"constitucional, pois enquanto a lei nacional não é editada, permanece sob a competência do Estado legislar sobre matéria que disciplina o regime jurídico da magistratura estadual;"},{"letra":"E","texto":"constitucional, pois repete as disposições e regras previstas na Lei Orgânica da Magistratura, as quais devem ser seguidas por todos os legisladores estaduais e do Distrito Federal."}],"gabarito":"C","pct":"79,65"},{"id":"2695000","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Jurisprudência dos Tribunais Superiores sobre Organização, Competências e Bens dos Entes Federativos","enunciado":"Norma do Estado Alfa reconhece o risco da atividade e a efetiva necessidade do porte de arma de fogo ao atirador desportivo integrante de entidades de desporto legalmente constituídas e ao vigilante de empresa de segurança privada. Diante do exposto e da jurisprudência do Supremo Tribunal Federal, é correto afirmar que a referida norma é:","alternativas":[{"letra":"A","texto":"inconstitucional, pois a Constituição da República veda a autorização de porte de arma de fogo ao atirador desportivo integrante de entidades de desporto legalmente constituídas;"},{"letra":"B","texto":"constitucional, pois com o objetivo de garantir a segurança pública, a definição dos requisitos para a concessão do porte de arma de fogo é de competência do Estado;"},{"letra":"C","texto":"constitucional, pois obedeceu aos requisitos estabelecidos pela Constituição, segundo a qual a concessão da respectiva autorização é de competência da Polícia Militar estadual;"},{"letra":"D","texto":"inconstitucional, pois a definição dos requisitos para a concessão do porte de arma de fogo é de competência da União, para garantir a uniformidade da regulamentação do tema no território nacional;"},{"letra":"E","texto":"constitucional, pois existe lei complementar da União autorizando os Estados-membros a legislarem sobre questões específicas acerca da matéria, a fim de suplementar as regras nacionais."}],"gabarito":"D","pct":"93,33"},{"id":"2695062","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Constitucional (CF/1988 e Doutrina)","assunto":"Das Súmulas Vinculantes (art. 103-A da CF/1988)","enunciado":"A súmula vinculante pode ser aprovada mediante decisão de dois terços dos ministros do STF para que, a partir de sua publicação, tenha efeito vinculante sobre:","alternativas":[{"letra":"A","texto":"demais instâncias do Poder Judiciário;"},{"letra":"B","texto":"Administração Pública direta e demais instâncias do Poder Judiciário;"},{"letra":"C","texto":"Administração Pública direta e indireta na esfera federal e os demais órgãos do Poder Judiciário;"},{"letra":"D","texto":"demais órgãos do Poder Judiciário e a Administração Pública direta e indireta, nas esferas federal, estadual e municipal;"},{"letra":"E","texto":"os órgãos deliberativos dos Poderes Legislativo, Executivo e Judiciário."}],"gabarito":"D","pct":"89,19"},{"id":"2120695","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Contratação Direta, Inexigibilidade e Dispensa (arts. 72 a 75 da Lei nº 14.133/2021)","enunciado":"O órgão responsável pela gestão dos recursos humanos no governo do estado Z solicitou a instauração de procedimento para a contratação da prestação de serviços médicos para os servidores públicos estaduais com regime de reembolso parcial de mensalidades pelo Estado.\n\n \nPor sua vez, a comissão responsável pelo procedimento de contratação estimou a cobertura mínima de atendimento e o valor máximo dos serviços médicos a ser apresentado nas propostas das operadoras de planos de saúde interessadas na prestação dos serviços aos servidores estaduais.\n\n \nNessa situação hipotética, o procedimento adequado de contratação é a","alternativas":[{"letra":"A","texto":"dispensa de licitação, pois o valor máximo dos serviços já foi previamente estabelecido pela administração."},{"letra":"B","texto":"inexigibilidade de licitação, com a realização de chamamento público, pois há viabilidade de contratação por meio de credenciamento."},{"letra":"C","texto":"licitação na modalidade diálogo competitivo, consideradas as diversas possibilidades de atendimento do objeto a ser contratado."},{"letra":"D","texto":"licitação na modalidade concurso, visto que se trata de serviço técnico cuja remuneração está previamente definida."},{"letra":"E","texto":"licitação na modalidade concorrência, devendo o critério de julgamento ser por técnica e preço."}],"gabarito":"B","pct":"58,42"},{"id":"2120696","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Princípios Implícitos, Reconhecidos e Infraconstitucionais","enunciado":"Enquanto pela tutela a administração exerce controle sobre outra pessoa jurídica por ela mesma instituída, pela autotutela o controle se exerce sobre os próprios atos, com a possibilidade de anular os ilegais e revogar os inconvenientes ou inoportunos, independentemente de recurso ao Poder Judiciário.\n\n \nMaria Sylvia Zanella Di Pietro. Direito administrativo.\n\n31.ª ed., Rio de Janeiro: Forense, 2018 (com adaptações).\n\n \nTendo como referência o fragmento de texto precedente, assinale a opção correta em relação ao princípio da autotutela.","alternativas":[{"letra":"A","texto":"A revogação da autorização de uso de bem público antes do prazo prescinde da salvaguarda de direitos adquiridos."},{"letra":"B","texto":"Constatada a presença de ilegalidade, impõe-se a anulação do ato administrativo, cuja declaração não se sujeita a prazo decadencial."},{"letra":"C","texto":"Constitui exemplo do exercício da autotutela a anulação de ato administrativo pelo gestor em decorrência de decisão em reclamação julgada pelo Supremo Tribunal Federal."},{"letra":"D","texto":"Passados mais de cinco anos da chegada ao tribunal de contas de processo que trata de registro da concessão de aposentadoria de servidor público, não poderá a referida corte de contas anular o ato."},{"letra":"E","texto":"Caso se verifique que pagamento de adicional remuneratório tenha decorrido de fraude em informação prestada pelo servidor beneficiário, pode a administração suprimir a parcela, desde que mediante provocação e em prévio processo administrativo."}],"gabarito":"D","pct":"53,41"},{"id":"2120697","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Jurisprudência dos Tribunais Superiores sobre Responsabilidade Civil do Estado","enunciado":"Após um plano de fuga bem sucedido, um presidiário praticou o crime de estupro de vulnerável, mediante violência, causando a morte da vítima.\n\n \nIndignados com o ocorrido, os pais da vítima ingressaram com ação judicial na qual requereram a condenação do Estado à concessão de pensão vitalícia e pagamento de indenização por danos morais, alegando a responsabilidade objetiva estatal e a falha na prestação do serviço de segurança pública como fundamentos do pedido.\n\n \nNessa situação hipotética, considerada a jurisprudência do Supremo Tribunal Federal sobre o tema, a demanda deverá ser julgada","alternativas":[{"letra":"A","texto":"procedente, pois a responsabilidade objetiva no caso torna presumida a ocorrência do dano moral."},{"letra":"B","texto":"improcedente no que se refere ao pedido de concessão de pensão vitalícia, dada a condição de vulnerabilidade da vítima."},{"letra":"C","texto":"procedente, em virtude da ocorrência da falha no serviço de segurança do presídio."},{"letra":"D","texto":"improcedente, pois não é possível estabelecer o nexo causal entre a fuga do preso e o dano causado em decorrência do crime."},{"letra":"E","texto":"improcedente, pois a responsabilidade civil por dano resultante de omissão do Estado é subjetiva."}],"gabarito":"D","pct":"73,80"},{"id":"2120698","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Terceiro Setor (OSs, OSCIPs, Sistema S e Fundações de Apoio)","enunciado":"As entidades criadas mediante autorização legal, com personalidade jurídica de direito privado, financiadas por contribuições compulsórias e que atuam sem sujeição hierárquica ao ente da administração, com a finalidade de promover atividades em cooperação com o Estado no atendimento de necessidades assistenciais e educacionais, denominam-se","alternativas":[{"letra":"A","texto":"fundações de apoio."},{"letra":"B","texto":"conselhos profissionais."},{"letra":"C","texto":"entidades paraestatais."},{"letra":"D","texto":"agências executivas."},{"letra":"E","texto":"empresas públicas."}],"gabarito":"C","pct":"69,40"},{"id":"2120699","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Tombamento - Conceitos e Decreto-Lei nº 25/1937","enunciado":"Com o objetivo de interditar a habitação em um conjunto de antigos imóveis residenciais em área caracterizada pela presença do comércio de bens e serviços, a prefeitura do município X decretou o tombamento de vinte e cinco casas localizadas no bairro, impondo aos proprietários a manutenção desses imóveis segundo suas características originais para a proteção do patrimônio histórico e cultural da cidade, sem previsão de indenização.\n\n \nNessa situação hipotética, o ato administrativo de tombamento é","alternativas":[{"letra":"A","texto":"nulo, em razão do desvio de finalidade, pois o tombamento não é instrumento apto à gestão de limitação urbanística municipal."},{"letra":"B","texto":"nulo, em virtude do vício de competência para a edição do decreto, a qual, no caso, é da União."},{"letra":"C","texto":"nulo, pois o ato de limitação à propriedade adequado ao caso seria a servidão administrativa."},{"letra":"D","texto":"legal, pois o tombamento para a preservação do patrimônio cultural prescinde de indenização."},{"letra":"E","texto":"anulável, mas poderia ser convalidado em ato posterior que fixasse justa indenização aos proprietários."}],"gabarito":"A","pct":"41,34"},{"id":"2120700","banca":"CEBRASPE (CESPE)","ano":"2022","orgao":"TJ MA","cargo":"Juiz Estadual (TJ MA)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Trâmite do Processo (arts. 5º a 10 e 29 a 50 da Lei nº 9.784/1999)","enunciado":"Antônio, secretário de administração do governo do estado Y, foi acusado por servidores públicos lotados naquela secretaria de ter nomeado sua empregada doméstica para o cargo em comissão de secretária no seu gabinete, o que foi seguido da extinção do vínculo de doméstica pela ocorrência de demissão.\n\n \nUm ano após a nomeação, instaurado processo disciplinar para apurar a conduta de Antônio, este, apesar de regularmente citado, não apresentou defesa nem se manifestou nos autos. Contudo, a comissão processante teve notícia de que o Ministério Público estadual o havia denunciado pela prática do crime de peculato desvio, em ação penal que se encontrava em grau de recurso.\n\n \nCiente da existência dos depoimentos de Antônio, de sua antiga empregada e de testemunhas nos autos da ação penal, o presidente da comissão processante solicitou ao tribunal de justiça a remessa de cópia dos autos judiciais para instruir o processo administrativo disciplinar.\n\n \nEm relação a essa situação hipotética, assinale a opção correta.","alternativas":[{"letra":"A","texto":"Eventual reforma da sentença condenatória no processo penal na qual se reconheça a insuficiência de provas resultará na absolvição de Antônio na seara disciplinar."},{"letra":"B","texto":"Em virtude do princípio da independência de instâncias, a solicitação do presidente da comissão processante deve ser indeferida pelo tribunal."},{"letra":"C","texto":"A revelia de Antônio na seara disciplinar impede a continuidade da instrução do processo administrativo."},{"letra":"D","texto":"As provas colhidas no processo penal só poderiam ser emprestadas ao disciplinar caso fosse comprovada a ausência de materialidade ou negativa de autoria."},{"letra":"E","texto":"As provas do processo penal podem ser emprestadas ao processo administrativo, independentemente do trânsito em julgado da sentença condenatória."}],"gabarito":"E","pct":"84,25"},{"id":"2695044","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Jurisprudência dos Tribunais Superiores sobre Licitações e Contratos Administrativos","enunciado":"O Município Alfa editou lei proibindo a participação em licitação e a contratação, pela Administração Pública daquele Município, de: I) agentes eletivos; II) ocupantes de cargo em comissão ou função de confiança; III) cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, de qualquer destes; IV) demais servidores públicos municipais; V) pessoas ligadas — por matrimônio ou parentesco, afim ou consanguíneo, até o terceiro grau, inclusive, ou por adoção — a servidores municipais não ocupantes de cargo em comissão ou função de confiança.\n\nFoi publicado edital de licitação pelo Município Alfa para aquisição de determinados bens, e diversas pessoas que se enquadram nos cinco itens acima e que tinham interesse em participar do certame judicializaram a questão.\n\nDe acordo com a jurisprudência do Supremo Tribunal Federal sobre o tema, a vedação de participação em licitação e contratação das pessoas elencadas nos itens acima:","alternativas":[{"letra":"A","texto":"I a V é constitucional, pois atende aos princípios da moralidade e impessoalidade da administração pública, e está em consonância com a vedação ao nepotismo;"},{"letra":"B","texto":"I a V é inconstitucional, do ponto de vista formal, porque Municípios não podem legislar sobre o tema, já que compete privativamente à União legislar sobre licitação e contratação pública;"},{"letra":"C","texto":"I a IV é constitucional, porque editada no exercício da competência legislativa suplementar do Município, mas deve ser excluída a proibição do item V, por violação à proporcionalidade, por não atender ao subprincípio da adequação;"},{"letra":"D","texto":"I e II é constitucional, porque editada no exercício de competência legislativa suplementar do Município, mas deve ser excluída a proibição dos itens III a V, pelo princípio da intranscendência subjetiva da impessoalidade;"},{"letra":"E","texto":"I a V é inconstitucional, do ponto de vista material, por violação aos princípios da isonomia e da competitividade, pois a licitação visa à contratação mais vantajosa para a Administração, devendo, a partir da técnica do sopesamento, mediante a utilização dos princípios da concordância prática ou harmonização e da proporcionalidade ou razoabilidade, prevalecer a melhor proposta, para se prestigiar a eficiência e a economicidade."}],"gabarito":"C","pct":"55,44"},{"id":"2695049","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Jurisprudência dos Tribunais Superiores sobre Concurso Público","enunciado":"No Estado Alfa, havia duas carreiras de Agentes Fiscais: a formada por cargos efetivos de Agente Fiscal 1, que exigia nível médio; e a de Agente Fiscal 2, que exigia nível superior para provimento originário do cargo efetivo.\n\nO Estado Alfa editou lei estadual unificando e reunindo as duas citadas carreiras na nova carreira de Auditor Fiscal, exigindo o nível superior de escolaridade nos próximos concursos.\n\nInstado a decidir sobre a constitucionalidade, incidenter tantum, da citada legislação, o magistrado deve considerar o teor de súmula vinculante do Supremo Tribunal Federal sobre o tema, que dispõe que é:","alternativas":[{"letra":"A","texto":"constitucional a unificação de carreiras distintas, desde que a própria lei já trate da modulação dos efeitos, exigindo nível superior apenas para os próximos concursos;"},{"letra":"B","texto":"constitucional a unificação de carreiras distintas que exigiam conhecimento técnico e especializado semelhantes para o exercício de suas atribuições, ainda que tal fato exceda substancialmente o nível de escolaridade declarado em lei;"},{"letra":"C","texto":"inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual fora anteriormente investido;"},{"letra":"D","texto":"constitucional a unificação de carreiras distintas, desde que reste comprovado, por meio de indicadores de produtividade, que a complexidade do trabalho aumentou de acordo com a ascensão na carreira por meio de promoções, decorrentes do tempo de serviço e participações em cursos de formação;"},{"letra":"E","texto":"inconstitucional toda modalidade de provimento derivado que propicie ao servidor investir-se em cargo diverso, pelo princípio do concurso público, sendo vedada a aplicação de qualquer modulação dos efeitos por razões de segurança jurídica ou excepcional interesse social."}],"gabarito":"C","pct":"82,62"},{"id":"2695051","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Jurisprudência dos Tribunais Superiores sobre Responsabilidade Civil do Estado","enunciado":"Durante uma operação da Polícia Militar no Estado Beta, na comunidade Alfa, Joaquim, menino de 5 anos, que dormia em sua cama, foi alvejado por uma bala perdida, morrendo imediatamente. Os pais de Joaquim ajuizaram ação indenizatória por danos morais em face do Estado Beta.\n\nNo caso em tela, observando a jurisprudência do Supremo Tribunal Federal sobre o tema, o magistrado deve aplicar a responsabilidade civil:","alternativas":[{"letra":"A","texto":"objetiva do Estado, sendo dever do Estado Beta provar a exclusão do nexo causal entre o ato e o dano, pois tal nexo é presumido;"},{"letra":"B","texto":"objetiva do Estado, sendo ônus dos pais de Joaquim provar a conduta, o dano e o nexo causal entre o ato e o dano, sendo necessária a comprovação de que os policiais agiram com culpa ou dolo;"},{"letra":"C","texto":"objetiva do Estado, sendo ônus dos pais de Joaquim provar a conduta e o dano, não podendo o Estado Beta invocar hipóteses excludentes da relação de causalidade e do elemento subjetivo da culpa ou do dolo;"},{"letra":"D","texto":"subjetiva do Estado, sendo ônus dos pais de Joaquim provar a conduta, o dano, o nexo causal entre o ato e o dano e o elemento subjetivo da culpa ou do dolo, caso não seja possível descobrir a origem da bala perdida;"},{"letra":"E","texto":"subjetiva do Estado, sendo dever do Estado Beta demonstrar a regularidade da operação policial, circunstância em que o ônus dos pais de Joaquim será de provar a conduta, o dano, o nexo causal entre o ato e o dano e o elemento subjetivo da culpa ou do dolo dos policiais."}],"gabarito":"A","pct":"88,92"},{"id":"2695053","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Da Responsabilização Administrativa (arts. 6º e 7º da Lei nº 12.846/2013)","enunciado":"O Estado Delta instaurou processo administrativo para apuração da responsabilidade da sociedade empresária Beta pela prática de ato contra a administração pública estadual, consistente em fraude à licitação.\n\nNo caso em tela, consoante dispõe a Lei federal nº 12.846/2013, conhecida como Lei Anticorrupção, a sociedade empresária Beta, na esfera administrativa, está sujeita a algumas sanções, como:","alternativas":[{"letra":"A","texto":"publicação ordinária da decisão condenatória, vedada a forma de extrato de sentença, a expensas da pessoa jurídica infratora;"},{"letra":"B","texto":"acordo de leniência, que necessariamente deve prever a identificação dos demais envolvidos na infração e a obtenção célere de informações e documentos que comprovem o ilícito sob apuração;"},{"letra":"C","texto":"perdimento dos bens, direitos ou valores que representem vantagem ou proveito direta ou indiretamente obtidos da infração, independentemente do direito de terceiro de boa-fé, face à supremacia do interesse público;"},{"letra":"D","texto":"proibição de receber incentivos, subsídios, subvenções, doações ou empréstimos de órgãos ou entidades públicas e de instituições financeiras públicas ou controladas pelo poder público, pelo prazo mínimo de dois e máximo de oito anos;"},{"letra":"E","texto":"multa, no valor de 0,1% a 20% do faturamento bruto do último exercício anterior ao da instauração do processo administrativo, excluídos os tributos, a qual nunca será inferior à vantagem auferida, quando for possível sua estimação."}],"gabarito":"E","pct":"77,70"},{"id":"2695056","banca":"FGV","ano":"2023","orgao":"TJ GO","cargo":"Juiz Estadual (TJ GO)","disciplina":"Direito Administrativo (Doutrina e Leis Federais)","assunto":"Tópicos Mesclados da Lei nº 9.784/1999","enunciado":"Adalto recebeu auto de infração lavrado pelo Núcleo de Fiscalização do Município de Estrela por inobservância do limite de ruído sonoro de estabelecimento comercial, definido em lei complementar, no dia 10 de setembro de 2023, às 22h, quando agente de fiscalização realizou ação in loco após o seu departamento receber denúncia anônima. A mensuração do ruído foi realizada no lado externo do empreendimento, com emprego dos equipamentos oficiais, sem que o proprietário ou qualquer responsável pelo empreendimento fosse cientificado, gerando um laudo técnico de medição. A multa foi aplicada no teto máximo conforme dosimetria prevista em Portaria do departamento.\n\nA respeito da situação concreta narrada, é correto afirmar que:","alternativas":[{"letra":"A","texto":"caso sobrevenha lei complementar que aumente o limite de ruído sonoro, esse novo patamar aplica-se imediatamente sobre o caso concreto, salvo se já houver decisão de primeira instância administrativa;"},{"letra":"B","texto":"a multa é ilegal, pois o processo de fiscalização não poderia ser deflagrado por denúncia anônima, o que subverte a ordem da agenda de fiscalização e mitigação da previsibilidade das ações administrativas e limita o direito de defesa do administrado;"},{"letra":"C","texto":"a multa é ilegal, visto que as infrações administrativas, as sanções e a correspondente dosimetria devem ser previstas em lei formal, e não em regulamento, tendo em vista o princípio da reserva absoluta de lei no Direito Administrativo;"},{"letra":"D","texto":"o devido processo legal do processo administrativo sancionador municipal em comento é informado pelos seguintes direitos: contraditório, ampla defesa, vedação ao sigilo do processamento, vedação à reformatio in pejus, condução do processo por autoridade competente e direito ao recurso de efeitos devolutivo e suspensivo;"},{"letra":"E","texto":"o poder público pode propor a substituição da multa por acordo com obrigações de dar, fazer ou não fazer, como o compromisso de observar o limite de ruído sonoro, desde que sejam cumpridos os requisitos do Art. 26 da LINDB, inclusive a motivação que indique ser o interesse público a solução consensual no caso concreto e, preferencialmente, que o acordo esteja previsto em regulamento."}],"gabarito":"E","pct":"72,00"}];
